/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R36 schema deployment runner
    Run Guid           : 97d0b16e-496e-4d28-9d41-40d766a59617
    Comparison Guid    : 5ffbc011-6717-4dc8-abe9-31cce01212ab
    Object             : Function SCrm.tvf_AccountsCheckForDuplicate
    Difference         : MissingInTarget
    Comparison hash    : A45A501BEC5673CDA477D61F731AB1F3E59FD1490C95BFAAC9FE3AAB46469610
    Definition SHA-256 : 1EC6B4964723BE2DC3DD62EDD6ED27BE4341B0374246D624BA415ABB338D0858
    Generated UTC      : 2026-08-05T07:43:28.3243800Z

    This file was materialized from the accepted source-definition snapshot. Review and commit it
    through the normal source-control process before promoting the release beyond the controlled
    environment in which it was generated.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SCrm].[tvf_AccountsCheckForDuplicate] 
(
   @DisplayName    NVARCHAR(100)   = NULL
)
RETURNS @Results TABLE
(
	Guid UNIQUEIDENTIFIER,
	FormattedAddress NVARCHAR(600),
	MatchScore INT
)
AS
BEGIN

	--Normalise value
	DECLARE @NormName       NVARCHAR(100) = UPPER(LTRIM(RTRIM(ISNULL(@DisplayName, ''))));


INSERT INTO @Results
(
	Guid,
	FormattedAddress,
	MatchScore
)
 SELECT 
        root_hobt.Guid,
        root_hobt.ConcatenatedNameCode,
		(

			-- Exact Name match
            + CASE WHEN @NormName <> ''
                   AND UPPER(LTRIM(RTRIM(root_hobt.Name))) = @NormName
                   THEN 40 ELSE 0 END

            -- SOUNDEX Name match (fuzzy, only if not exact)
            + CASE WHEN @NormName <> ''
                   AND root_hobt.Name <> ''
                   AND SOUNDEX(root_hobt.Name) = SOUNDEX(@DisplayName)
                   AND UPPER(LTRIM(RTRIM(root_hobt.Name))) <> @NormName
                   THEN 15 ELSE 0 END
        ) AS MatchScore

    FROM SCrm.Accounts AS root_hobt
    WHERE
			root_hobt.RowStatus NOT IN (0,254)
		AND (@NormName <> '' AND root_hobt.Name <> '' AND SOUNDEX(root_hobt.Name) = SOUNDEX(@DisplayName))
		 
		
				
			
		
		DELETE FROM @Results WHERE MatchScore <= 0;
		

		RETURN;

END;
GO

