/* Deploy StoredProcedure SFin.InvoiceScheduleMonthlyDrawdownAmendmentAssert using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SFin.InvoiceScheduleMonthlyDrawdownAmendmentAssert.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SFin].[InvoiceScheduleMonthlyDrawdownAmendmentAssert]')
GO

CREATE OR ALTER PROCEDURE [SFin].[InvoiceScheduleMonthlyDrawdownAmendmentAssert]
(
    @UserId INT,
    @InvoiceScheduleGuid UNIQUEIDENTIFIER,
    @BypassReadOnlyForAutomationReenable BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @InvoiceScheduleId INT,
        @TriggerName NVARCHAR(100),
        @AutomatedInvoiceProcessingMode TINYINT = 0;

    SELECT
        @InvoiceScheduleId = invsch.ID,
        @TriggerName = triggerType.Name
    FROM SFin.InvoiceSchedules AS invsch
    INNER JOIN SFin.InvoiceScheduleTrigger AS triggerType
        ON triggerType.ID = invsch.TriggerId
       AND triggerType.RowStatus <> 0
       AND triggerType.RowStatus <> 254
    WHERE invsch.Guid = @InvoiceScheduleGuid
      AND invsch.RowStatus <> 0
      AND invsch.RowStatus <> 254;

    IF @InvoiceScheduleId IS NULL
    BEGIN
        THROW 51000, 'Invoice schedule was not found or is inactive.', 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM SCore.ObjectSecurityForUser_CanWritev AS canWrite
        WHERE canWrite.Guid = @InvoiceScheduleGuid
          AND canWrite.ID = @UserId
    )
    BEGIN
        THROW 51000, 'The current user does not have permission to amend this invoice schedule.', 1;
    END;

    IF @TriggerName <> N'Monthly Drawdowns'
    BEGIN
        THROW 51000, 'Only Monthly Drawdowns are supported by the monthly drawdown amendment operation.', 1;
    END;

    IF @BypassReadOnlyForAutomationReenable = 1
    BEGIN
        RETURN;
    END;

    /*
        CYB-464: direct amendments are allowed only when every active Job linked to
        this schedule remains in Automated invoicing mode. Quote schedules that have
        not yet created a Job retain their existing editable behaviour.
    */
    IF EXISTS
    (
        SELECT 1
        FROM SSop.QuoteItems AS qi
        INNER JOIN SJob.Jobs AS j
            ON j.ID = qi.CreatedJobId
           AND j.RowStatus <> 0
           AND j.RowStatus <> 254
        WHERE qi.InvoicingSchedule = @InvoiceScheduleId
          AND qi.CreatedJobId > 0
          AND qi.RowStatus <> 0
          AND qi.RowStatus <> 254
          AND j.InvoiceProcessingMode <> @AutomatedInvoiceProcessingMode
    )
    BEGIN
        THROW 51000, 'Monthly drawdowns can only be amended directly while every related Job is in Automated invoicing mode.', 1;
    END;
END;
GO

GO

/* Deploy StoredProcedure SFin.JobInvoiceProcessingMode_Set using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SFin.JobInvoiceProcessingMode_Set.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SFin].[JobInvoiceProcessingMode_Set]')
GO
/* =========================================================
   4) Set Job InvoiceProcessingMode (audited + synced)
   ========================================================= */
CREATE OR ALTER PROCEDURE [SFin].[JobInvoiceProcessingMode_Set]
(
      @JobGuid            UNIQUEIDENTIFIER
    , @NewMode            TINYINT
    , @ChangedByUserGuid  UNIQUEIDENTIFIER = NULL
    , @Reason             NVARCHAR(500) = N''
    , @Source             NVARCHAR(50) = N'UI'
	, @UserId			  INT = -1
)
AS
BEGIN
    SET NOCOUNT ON;

    IF (@NewMode NOT IN (0,1,2))
        THROW 50001, 'Invalid InvoiceProcessingMode. Allowed values: 0=Automated,1=Manual,2=Paused.', 1;

    DECLARE @JobId INT, @OldMode TINYINT, @ChangedByUserId INT;

    SELECT TOP (1)
          @JobId = j.ID
        , @OldMode = j.InvoiceProcessingMode
    FROM SJob.Jobs j
    WHERE j.Guid = @JobGuid
      AND j.RowStatus NOT IN (0,254);

    IF (@JobId IS NULL)
        THROW 50002, 'Job not found (or inactive).', 1;

	DECLARE @UserGuid UNIQUEIDENTIFIER;
	SET @ChangedByUserId = @UserId;


	SELECT @UserGuid = Guid 
	FROM SCore.Identities
	WHERE ID = @UserId;
	
	


    IF (@OldMode = @NewMode)
        RETURN;

    BEGIN TRAN;

    UPDATE j
    SET
          j.InvoiceProcessingMode = @NewMode
        , j.ManualInvoicingEnabled = CASE WHEN @NewMode = 1 THEN 1 ELSE 0 END
    FROM SJob.Jobs j
    WHERE j.ID = @JobId;

    INSERT INTO SFin.InvoiceProcessingModeHistory
    (
          JobId, JobGuid, OldMode, NewMode
        , ChangedByUserId, ChangedByUserGuid
        , Reason, Source
    )
    VALUES
    (
          @JobId, @JobGuid, @OldMode, @NewMode
        , @ChangedByUserId, @UserGuid
        , ISNULL(@Reason, N''), ISNULL(@Source, N'UI')
		
    );

    COMMIT;
END
GO
GO

/* Deploy StoredProcedure SFin.SageInboundDocumentStatus_TryClaim using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SFin.SageInboundDocumentStatus_TryClaim.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SFin].[SageInboundDocumentStatus_TryClaim]')
GO
CREATE OR ALTER PROCEDURE [SFin].[SageInboundDocumentStatus_TryClaim]
(
    @CymBuildDocumentGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

    IF @CymBuildDocumentGuid IS NULL
       OR @CymBuildDocumentGuid = '00000000-0000-0000-0000-000000000000'
    BEGIN
        THROW 51000,
              'A valid CymBuild document Guid is required.',
              1;
    END;

    DECLARE @NowUtc DATETIME2(7) = SYSUTCDATETIME();

    DECLARE @Claimed TABLE
    (
        [ClaimSucceeded]         BIT              NOT NULL,
        [ID]                     BIGINT           NULL,
        [Guid]                   UNIQUEIDENTIFIER NULL,
        [CymBuildEntityTypeID]   INT              NULL,
        [CymBuildDocumentGuid]   UNIQUEIDENTIFIER NULL,
        [CymBuildDocumentID]     BIGINT           NULL,
        [InvoiceRequestID]       INT              NULL,
        [TransactionID]          BIGINT           NULL,
        [JobID]                  INT              NULL,
        [SageDataset]            NVARCHAR(30)     NULL,
        [SageAccountReference]   NVARCHAR(100)    NULL,
        [SageDocumentNo]         NVARCHAR(100)    NULL,
        [StatusCode]             NVARCHAR(30)     NULL,
        [IsInProgress]           BIT              NULL,
        [InProgressClaimedOnUtc] DATETIME2(7)     NULL
    );

    ;WITH [Claimable] AS
    (
        SELECT TOP (1)
            s.[ID]
        FROM [SFin].[SageInboundDocumentStatus] AS s
            WITH
            (
                UPDLOCK,
                READPAST,
                READCOMMITTEDLOCK,
                ROWLOCK
            )
        WHERE s.[CymBuildDocumentGuid] = @CymBuildDocumentGuid
          AND s.[RowStatus] <> 0
          AND s.[RowStatus] <> 254
          AND ISNULL(s.[IsInProgress], 0) = 0
        ORDER BY
            s.[ID]
    )
    UPDATE s
    SET
        s.[IsInProgress] = 1,
        s.[InProgressClaimedOnUtc] = @NowUtc,
        s.[UpdatedByUserID] = [SCore].[GetCurrentUserId](),
        s.[UpdatedDateTimeUTC] = @NowUtc
    OUTPUT
        CAST(1 AS BIT),
        inserted.[ID],
        inserted.[Guid],
        inserted.[CymBuildEntityTypeID],
        inserted.[CymBuildDocumentGuid],
        inserted.[CymBuildDocumentID],
        inserted.[InvoiceRequestID],
        inserted.[TransactionID],
        inserted.[JobID],
        inserted.[SageDataset],
        inserted.[SageAccountReference],
        inserted.[SageDocumentNo],
        inserted.[StatusCode],
        inserted.[IsInProgress],
        inserted.[InProgressClaimedOnUtc]
    INTO @Claimed
    (
        [ClaimSucceeded],
        [ID],
        [Guid],
        [CymBuildEntityTypeID],
        [CymBuildDocumentGuid],
        [CymBuildDocumentID],
        [InvoiceRequestID],
        [TransactionID],
        [JobID],
        [SageDataset],
        [SageAccountReference],
        [SageDocumentNo],
        [StatusCode],
        [IsInProgress],
        [InProgressClaimedOnUtc]
    )
    FROM [SFin].[SageInboundDocumentStatus] AS s
    INNER JOIN [Claimable] AS c
        ON c.[ID] = s.[ID];

    IF EXISTS
    (
        SELECT 1
        FROM @Claimed AS c
    )
    BEGIN
        SELECT
            c.[ClaimSucceeded],
            c.[ID],
            c.[Guid],
            c.[CymBuildEntityTypeID],
            c.[CymBuildDocumentGuid],
            c.[CymBuildDocumentID],
            c.[InvoiceRequestID],
            c.[TransactionID],
            c.[JobID],
            c.[SageDataset],
            c.[SageAccountReference],
            c.[SageDocumentNo],
            c.[StatusCode],
            c.[IsInProgress],
            c.[InProgressClaimedOnUtc]
        FROM @Claimed AS c;
    END;
    ELSE
    BEGIN
        SELECT
            CAST(0 AS BIT)                   AS [ClaimSucceeded],
            CAST(NULL AS BIGINT)             AS [ID],
            CAST(NULL AS UNIQUEIDENTIFIER)   AS [Guid],
            CAST(NULL AS INT)                AS [CymBuildEntityTypeID],
            CAST(NULL AS UNIQUEIDENTIFIER)   AS [CymBuildDocumentGuid],
            CAST(NULL AS BIGINT)             AS [CymBuildDocumentID],
            CAST(NULL AS INT)                AS [InvoiceRequestID],
            CAST(NULL AS BIGINT)             AS [TransactionID],
            CAST(NULL AS INT)                AS [JobID],
            CAST(NULL AS NVARCHAR(30))       AS [SageDataset],
            CAST(NULL AS NVARCHAR(100))      AS [SageAccountReference],
            CAST(NULL AS NVARCHAR(100))      AS [SageDocumentNo],
            CAST(NULL AS NVARCHAR(30))       AS [StatusCode],
            CAST(NULL AS BIT)                AS [IsInProgress],
            CAST(NULL AS DATETIME2(7))       AS [InProgressClaimedOnUtc];
    END;
END;
