SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create function [SFin].[tvf_TransactionSageSubmissionMonitor]')
GO
PRINT (N'Create function [SFin].[tvf_TransactionSageSubmissionMonitor]')
