CREATE OR ALTER PROCEDURE [SJob].[SubContractorInvoicesUpsert]
	(	
		@Guid UNIQUEIDENTIFIER,
		@InvoiceNumber NVARCHAR(100),
		@InvoiceDate DATE,
		@DescriptionOfWork NVARCHAR(MAX),
		@SupportingComments NVARCHAR(MAX),
		@ActivityGuid UNIQUEIDENTIFIER,
		@MilestoneGuid UNIQUEIDENTIFIER,
		@ValueWithVAT DECIMAL(19,2),
		@ValueWithoutVAT DECIMAL(19,2),
		@SubContractorName NVARCHAR(100),
		@JobGuid UNIQUEIDENTIFIER,
		@SubContractorGuid UNIQUEIDENTIFIER
		
	)
AS
BEGIN
	DECLARE 
			@ActivityId		BIGINT,
			@MilestoneId	BIGINT,
			@JobId			INT,
			@IsInsert		BIT,
			@SubContractorId INT,
			@IsPurchaseLedger BIT;


	SELECT @MilestoneId = ID
	FROM SJob.Milestones
	WHERE ([Guid] = @MilestoneGuid);

	SELECT @ActivityId = ID
	FROM SJob.Activities 
	WHERE ([Guid] = @ActivityGuid);

	SELECT @JobId = ID
	FROM SJob.Jobs
	WHERE ([Guid] = @JobGuid);

	SELECT 
			@SubContractorId = ID,
			@IsPurchaseLedger = IsPurchaseLedger
	FROM SCrm.Accounts
	WHERE ([Guid] = @SubContractorGuid)


	IF(@IsPurchaseLedger = 0)
		THROW 60361, N'Account must be set to a purchase ledger. ', 1;

	

	EXEC SCore.UpsertDataObject @Guid = @Guid,					-- uniqueidentifier
							@SchemeName = N'SJob',				-- nvarchar(255)
							@ObjectName = N'SubContractorInvoices',				-- nvarchar(255)
							@IncludeDefaultSecurity = 0,
							@IsInsert = @IsInsert OUTPUT	-- bit

    IF (@IsInsert = 1)
	BEGIN
		INSERT	SJob.SubContractorInvoices
			 (
				RowStatus,
				Guid,
				InvoiceNumber,
				InvoiceDate,
				DescriptionOfWork,
				SupportingComments,
				ActivityId,
				MilestoneId,
				ValueWithVAT,
				ValueWithoutVAT,
				SubContractorName,
				JobId,
				SubContractorId
			) 
		VALUES
			 (
				 1,								-- RowStatus - tinyint
				 @Guid,							-- Guid - uniqueidentifier
				 @InvoiceNumber,
				 @InvoiceDate,
				 @DescriptionOfWork,
				 @SupportingComments,
				 @ActivityId,
				 @MilestoneId,
				 @ValueWithVAT,
				 @ValueWithoutVAT,
				 @SubContractorName,
				 @JobId,
				 @SubContractorId
			 );
	END;
	ELSE
	BEGIN
		UPDATE	SJob.SubContractorInvoices
		SET		
				InvoiceNumber = @InvoiceNumber,
				InvoiceDate = @InvoiceDate,
				DescriptionOfWork = @DescriptionOfWork,
				SupportingComments = @SupportingComments,
				ActivityId = @ActivityId,
				MilestoneId = @MilestoneId,
				ValueWithVAT = @ValueWithVAT,
				ValueWithoutVAT = @ValueWithoutVAT,
				SubContractorName = @SubContractorName,
				SubContractorId = @SubContractorId
		WHERE	(Guid = @Guid);
	END;


END;
GO
