        DEALLOCATE cur_wsng;

        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'WorkflowStatusNotificationGroups', N'Insert', @cnt, N'Inserted distinct missing workflow notification groups only.';


        /* ========================================================================================
