                    AND LOWER(LTRIM(RTRIM(t.Code))) = LOWER(LTRIM(RTRIM(s.Code)))
                )
                OR LOWER(LTRIM(RTRIM(t.Name))) = LOWER(LTRIM(RTRIM(s.Name)))
           )
        WHERE s.RunGuid = @RunGuid
