/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_Default using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_Default.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_Default]')
GO
PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_Default]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_Default]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RunGuid IS NULL
        THROW 62200, 'RunGuid is required for OnBoarding entity selection defaults.', 1;

    EXEC SMigration.OnboardingEntityScope_Seed;

    DECLARE
        @SelectionGuid UNIQUEIDENTIFIER,
        @EntityScopeGuid UNIQUEIDENTIFIER,
        @EntityCode NVARCHAR(100),
        @DefaultSelected BIT;

    DECLARE selection_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            NEWID() AS SelectionGuid,
            es.Guid AS EntityScopeGuid,
            es.Code AS EntityCode,
            es.DefaultSelected
        FROM SMigration.Onboarding_EntityScope AS es
        WHERE es.RowStatus NOT IN (0,254)
          AND es.IsSupportData = 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM SMigration.Onboarding_RunEntitySelections AS existing
              WHERE existing.RunGuid = @RunGuid
                AND existing.EntityCode = es.Code
          )
        ORDER BY es.DisplayOrder;

    OPEN selection_cursor;
    FETCH NEXT FROM selection_cursor INTO @SelectionGuid, @EntityScopeGuid, @EntityCode, @DefaultSelected;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @SelectionGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_RunEntitySelections';

        INSERT INTO SMigration.Onboarding_RunEntitySelections
        (
            Guid,
            RowStatus,
            RunGuid,
            EntityScopeGuid,
            EntityCode,
            IsSelected,
            SelectionSource,
            SelectedByUserId,
            SelectedOnUtc
        )
        VALUES
        (
            @SelectionGuid,
            1,
            @RunGuid,
            @EntityScopeGuid,
            @EntityCode,
            @DefaultSelected,
            N'Default',
            ISNULL(SCore.GetCurrentUserId(), -1),
            SYSUTCDATETIME()
        );

        FETCH NEXT FROM selection_cursor INTO @SelectionGuid, @EntityScopeGuid, @EntityCode, @DefaultSelected;
    END;

    CLOSE selection_cursor;
    DEALLOCATE selection_cursor;

    UPDATE sel
    SET
        RowStatus = CASE WHEN sel.RowStatus IN (0,254) THEN 1 ELSE sel.RowStatus END,
        EntityScopeGuid = es.Guid
    FROM SMigration.Onboarding_RunEntitySelections AS sel
    INNER JOIN SMigration.Onboarding_EntityScope AS es
        ON es.Code = sel.EntityCode
       AND es.RowStatus NOT IN (0,254)
       AND es.IsSupportData = 0
    WHERE sel.RunGuid = @RunGuid;
END;
GO
GO

/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_List using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_List.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_List]')
GO
PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_List]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_List]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @RunGuid IS NULL
        THROW 62210, 'RunGuid is required to list OnBoarding entity selections.', 1;

    EXEC SMigration.OnboardingEntityScope_Seed;

    SELECT
        es.Guid AS EntityScopeGuid,
        es.Code AS EntityCode,
        es.Name AS EntityName,
        es.Description,
        es.StageTableName,
        es.DisplayOrder,
        CONVERT(BIT, ISNULL(sel.IsSelected, es.DefaultSelected)) AS IsSelected,
        es.DefaultSelected,
        es.CanDeselect,
        es.IsRequired,
        es.RequiredDependencyCodes,
        sel.Guid AS SelectionGuid,
        ISNULL(sel.SelectionSource, N'Default') AS SelectionSource,
        ISNULL(CONVERT(NVARCHAR(30), sel.SelectedOnUtc, 126), N'') AS SelectedOnUtc,
        es.Category,
        es.ScopeType,
        es.IsImplemented,
        es.IsSupportData,
        es.HandlerKey,
        es.PrimaryEntityTypeGuid,
        es.SourceSchemaName,
        es.SourceTableName
    FROM SMigration.Onboarding_EntityScope AS es
    LEFT JOIN SMigration.Onboarding_RunEntitySelections AS sel
        ON sel.RunGuid = @RunGuid
       AND sel.EntityCode = es.Code
       AND sel.RowStatus NOT IN (0,254)
    WHERE es.RowStatus NOT IN (0,254)
      AND es.IsSupportData = 0
    ORDER BY
        CASE es.Category
            WHEN N'Access Foundation' THEN 10
            WHEN N'Operational Configuration' THEN 20
            WHEN N'Additional Eligible Record Types' THEN 30
            WHEN N'Internal / Support Data' THEN 90
            ELSE 80
        END,
        es.DisplayOrder,
        es.Code;
END;
GO
