/* Deploy StoredProcedure SMigration.OnboardingRunStageSelection_Save using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunStageSelection_Save.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
