CREATE OR ALTER PROCEDURE [SSop].[CriticalProjectNotesDelete] 
								@Guid UNIQUEIDENTIFIER 
AS
BEGIN

	EXEC SCore.DeleteDataObject @Guid = @Guid	-- uniqueidentifier

	UPDATE	a 
	SET		RowStatus = 254
	FROM	SSop.CriticalProjectNotes a
	WHERE	(Guid = @Guid)
END;

