/* Deploy StoredProcedure SSop.CriticalProjectNotesUpsert using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SSop.CriticalProjectNotesUpsert.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SSop].[CriticalProjectNotesUpsert]')
GO

CREATE OR ALTER PROCEDURE [SSop].[CriticalProjectNotesUpsert]
	(
		@Guid						UNIQUEIDENTIFIER,
		@Note						NVARCHAR(MAX),
		@CreatedByGuid				UNIQUEIDENTIFIER,
		@ParentGuid					UNIQUEIDENTIFIER
	)
AS
	BEGIN
	
		
		DECLARE @ProjectId			INT,
				@ParentEntityTypeId INT,
				@CreatedById		INT;


		DECLARE 
				@EnquiryEntityType	INT = 83,
				@QuoteEntityType	INT = 55,
				@JobEntityType		INT = 9;


		--Get user ID.
		SELECT @CreatedById = ID
		FROM SCore.Identities 
		WHERE Guid = @CreatedByGuid

		
		--Get the entity type.
		SELECT @ParentEntityTypeId = EntityTypeId
		FROM SCore.DataObjects
		WHERE Guid = @ParentGuid

		--Enquiry
		IF(@ParentEntityTypeId = @EnquiryEntityType)
			BEGIN

				SELECT @ProjectId = root_hobt.ProjectId
				FROM SSop.Enquiries root_hobt
				WHERE root_hobt.Guid = @ParentGuid;

			END;
		--Quote
		ELSE IF(@ParentEntityTypeId = @QuoteEntityType)
			BEGIN

				SELECT @ProjectId = root_hobt.ProjectId
				FROM SSop.Quotes root_hobt
				WHERE root_hobt.Guid = @ParentGuid;

			END;
		--Job
		ELSE IF(@ParentEntityTypeId = @JobEntityType)
			BEGIN

				SELECT @ProjectId = root_hobt.ProjectId
				FROM SJob.Jobs root_hobt
				WHERE root_hobt.Guid = @ParentGuid;
			END;



	
		DECLARE @IsInsert BIT
		EXEC SCore.UpsertDataObject
			@Guid		= @Guid,					
			@SchemeName = N'SSop',						
			@ObjectName = N'CriticalProjectNotes',				
			@IsInsert   = @IsInsert OUTPUT	-- bit



		IF (@IsInsert = 1)
			BEGIN
				INSERT SSop.CriticalProjectNotes
						(
							RowStatus,
							Guid,
							Note,
							CreatedBy,
							ParentGuid,
							ProjectId
						)
				VALUES
						(
							1,	-- RowStatus - tinyint
							@Guid,	-- Guid - uniqueidentifier
							@Note,
							@CreatedById,
							@ParentGuid,
							@ProjectId
						)
			END
		ELSE
			BEGIN
				UPDATE SSop.CriticalProjectNotes
				SET		
					Note = @Note
				WHERE
					([Guid] = @Guid)
			END
	END
GO
GO

/* Deploy StoredProcedure SSop.EnquiryCreateQuotes using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SSop.EnquiryCreateQuotes.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SSop].[EnquiryCreateQuotes]')
GO
PRINT (N'Create procedure [SSop].[EnquiryCreateQuotes]')
GO
CREATE OR ALTER PROCEDURE [SSop].[EnquiryCreateQuotes]
	(@Guid UNIQUEIDENTIFIER)
AS
BEGIN


	DECLARE @ReadyForQuoteStatus UNIQUEIDENTIFIER = 'EB867FA0-9608-4CC7-93BE-CC8E8140E8F0'
			
	
	DECLARE 
		@Sustainability UNIQUEIDENTIFIER = 'D37AB015-DA10-4DD5-8C64-CE256546A508',
		@SustainabilityCompliance UNIQUEIDENTIFIER = '7ADC0989-A468-47E5-A206-DAEC008F9E9D',
		@BuildingEnvelope UNIQUEIDENTIFIER = '4927F7DD-3A47-424B-B890-BAE9FFD052C6',
		@BuildingEnvelopeUK UNIQUEIDENTIFIER = '1882472F-9976-4D25-8BF6-A91F7BE1AA3F',
		@StructuralEngineering UNIQUEIDENTIFIER = '573CBCE7-7F60-49A1-A8D5-B4074C08E412',
		@StructuralEngineeringUK UNIQUEIDENTIFIER = 'AEBD6E67-7883-405D-A234-8377722281C1';


	DECLARE 
		@ValueOfWork DECIMAL(19,2);


	SELECT @ValueOfWork = root_hobt.ValueOfWork
	FROM SSop.Enquiries root_hobt
	WHERE root_hobt.Guid = @Guid


	IF(@ValueOfWork <= 0)
	BEGIN
		;
		THROW 60000, N'Value of work must be set!', 1;
	END;


	

	IF (NOT EXISTS
	 (
		 
			SELECT 1 
			FROM SCore.DataObjectTransition AS dot
			JOIN SCore.WorkflowStatus as ws ON (ws.ID = dot.StatusID)
			WHERE 
				(dot.DataObjectGuid = @Guid) AND
				(ws.Guid = @ReadyForQuoteStatus)
	 )
	 AND NOT EXISTS
			(
				SELECT 1 FROM
				SSop.Enquiries 
				WHERE 
					(Guid = @Guid)
				AND (IsReadyForQuoteReview = 1)
			)
	   )
	   /*
			Enquiries belonging to the below org units should not be
			checked if they have "Ready for Quote" status.
	   */
	   AND NOT EXISTS
	   (
			SELECT 1 
			FROM SSop.Enquiries root_hobt
			JOIN SCore.OrganisationalUnits org ON (root_hobt.OrganisationalUnitID = org.ID)
			WHERE 
					(root_hobt.Guid = @Guid)
				AND (org.Guid NOT IN 
							(
								@Sustainability,
								@SustainabilityCompliance,
								@BuildingEnvelope,
								@BuildingEnvelopeUK,
								@StructuralEngineering,
								@StructuralEngineeringUK
							)
					)
		)
	BEGIN
		;
		THROW 60000, N'The enquiry must be marked ready for review first.', 1;
	END;

	IF (NOT EXISTS
	 (
		 SELECT 1
		 FROM	SSop.EnquiryServices AS es
		 JOIN	SSop.Enquiries		 AS e ON (e.ID = es.EnquiryId)
		 WHERE	(e.Guid = @Guid)
			AND (NOT EXISTS
			 (
				 SELECT 1
				 FROM	SSop.Quotes AS q
				 WHERE	(q.EnquiryServiceID = es.ID)
					AND (q.RowStatus NOT IN (0, 254))
			 )
				)
	 )
	   )
	BEGIN
		;
		THROW 60000, N'Nothing to create', 1;
	END;

	/* Get the details of the enquiry. */
	DECLARE @PropertyGuid					UNIQUEIDENTIFIER,
			@PropertyNameNumber				NVARCHAR(50),
			@PropertyAddressLine1			NVARCHAR(50),
			@PropertyAddressLine2			NVARCHAR(50),
			@PropertyAddressLine3			NVARCHAR(50),
			@PropertyTown					NVARCHAR(50),
			@PropertyCountyGuid				UNIQUEIDENTIFIER,
			@PropertyPostCode				NVARCHAR(50),
			@PropertyCountryGuid			UNIQUEIDENTIFIER,
			@AssetJSONDetails				NVARCHAR(500),
			@ClientAccountGuid				UNIQUEIDENTIFIER,
			@ClientAddressGuid				UNIQUEIDENTIFIER,
			@ClientContactGuid				UNIQUEIDENTIFIER,
			@ClientName						NVARCHAR(250),
			@ClientAddressNameNumber		NVARCHAR(50),
			@ClientAddressLine1				NVARCHAR(50),
			@ClientAddressLine2				NVARCHAR(50),
			@ClientAddressLine3				NVARCHAR(50),
			@ClientAddressTown				NVARCHAR(50),
			@ClientAddressCountyGuid		UNIQUEIDENTIFIER,
			@ClientAddressPostCode			NVARCHAR(50),
			@ClientAddressCountryGuid		UNIQUEIDENTIFIER,
			@ContactForClientGuid			UNIQUEIDENTIFIER,
			@ClientContactDisplayName		NVARCHAR(250), --client contact
			@ClientContactDetailType		SMALLINT, 
			@ClientContactDetailTypeName	NVARCHAR(100),
			@ClientContactDetailTypeValue	NVARCHAR(250),
			@ClientContactDetailGuid		UNIQUEIDENTIFIER,
			@AgentAccountGuid				UNIQUEIDENTIFIER,
			@AgentAddressGuid				UNIQUEIDENTIFIER,
			@AgentContactGuid				UNIQUEIDENTIFIER,
			@AgentName						NVARCHAR(250),
			@AgentAddressNameNumber			NVARCHAR(50),
			@AgentAddressLine1				NVARCHAR(50),
			@AgentAddressLine2				NVARCHAR(50),
			@AgentAddressLine3				NVARCHAR(50),
			@AgentAddressTown				NVARCHAR(50),
			@AgentAddressCountyGuid			UNIQUEIDENTIFIER,
			@AgentAddressPostCode			NVARCHAR(50),
			@AgentAddressCountryGuid		UNIQUEIDENTIFIER,
			@ContactForAgentGuid			UNIQUEIDENTIFIER,
			@AgentContactDisplayName		NVARCHAR(250),
			@AgentContactDetailType		    SMALLINT, 
			@AgentContactDetailTypeName	    NVARCHAR(100),
			@AgentContactDetailTypeValue	NVARCHAR(250),
			@AgentContactDetailGuid		    UNIQUEIDENTIFIER,
			@AccountStatusGuid				UNIQUEIDENTIFIER,
			@QuotingUserGuid				UNIQUEIDENTIFIER,
			@FinanceAccountGuid				UNIQUEIDENTIFIER,
			@FinanceAddressGuid				UNIQUEIDENTIFIER,
			@FinanceContactGuid				UNIQUEIDENTIFIER,
			@FinanceName					NVARCHAR(250),
			@FinanceAddressNameNumber		NVARCHAR(50),
			@FinanceAddressLine1			NVARCHAR(50),
			@FinanceAddressLine2			NVARCHAR(50),
			@FinanceAddressLine3			NVARCHAR(50),
			@FinanceAddressTown				NVARCHAR(50),
			@FinanceAddressCountyGuid		UNIQUEIDENTIFIER,
			@FinanceAddressPostCode			NVARCHAR(50),
			@FinanceAddressCountryGuid		UNIQUEIDENTIFIER,
			@ContactForFinanceGuid			UNIQUEIDENTIFIER,
			@FinanceContactDisplayName		NVARCHAR(250),
			@FinanceContactDetailType		SMALLINT, 
			@FinanceContactDetailTypeName	NVARCHAR(100),
			@FinanceContactDetailTypeValue	NVARCHAR(250),
			@FinanceContactDetailGuid		UNIQUEIDENTIFIER,
			@ProjectGuid					UNIQUEIDENTIFIER,
			@IsClientFinanceAccount			BIT,
			@JobTypeId						INT, 
			@BillingInstruction				NVARCHAR(MAX),
			@ContractGuid					UNIQUEIDENTIFIER,
			@AgentContractGuid              UNIQUEIDENTIFIER


	SELECT	@PropertyGuid					= uprn.Guid,
			@PropertyNameNumber				= e.PropertyNameNumber,
			@PropertyAddressLine1			= e.PropertyAddressLine1,
			@PropertyAddressLine2			= e.PropertyAddressLine2,
			@PropertyAddressLine3			= e.PropertyAddressLine3,
			@PropertyTown					= e.PropertyTown,
			@PropertyCountyGuid				= uprnc.Guid,
			@PropertyPostCode				= e.PropertyPostCode,
			@PropertyCountryGuid			= uprncr.Guid,
			@AssetJSONDetails				= e.AssetJSONDetails,
			@ClientAccountGuid				= c.Guid,
			@ClientAddressGuid				= c_add.Guid,
			@ClientContactGuid				= c_con.Guid,
			@ClientName						= e.ClientName,
			@ClientAddressNameNumber		= e.ClientAddressNameNumber,
			@ClientAddressLine1				= e.ClientAddressLine1,
			@ClientAddressLine2				= e.ClientAddressLine2,
			@ClientAddressLine3				= e.ClientAddressLine3,
			@ClientAddressTown				= e.ClientAddressTown,
			@ClientAddressCountyGuid		= c_add_c.Guid,
			@ClientAddressPostCode			= e.ClientAddressPostCode,
			@ClientAddressCountryGuid		= c_add_cr.Guid,
			@ClientContactDisplayName		= e.ClientContactDisplayName,
			@ClientContactDetailType		= e.ClientContactDetailType, 
			@ClientContactDetailTypeName	= e.ClientContactDisplayName,
			@ClientContactDetailTypeValue	= e.ClientContactDetailTypeValue,
			@AgentAccountGuid				= a.Guid,
			@AgentAddressGuid				= a_add.Guid,
			@AgentContactGuid				= a_con.Guid,
			@AgentName						= e.AgentName,
			@AgentAddressNameNumber			= e.AgentAddressNameNumber,
			@AgentAddressLine1				= e.AgentAddressLine1,
			@AgentAddressLine2				= e.AgentAddressLine2,
			@AgentAddressLine3				= e.AgentAddressLine3,
			@AgentAddressTown				= e.AgentTown,
			@AgentAddressCountyGuid			= a_add_c.Guid,
			@AgentAddressPostCode			= e.AgentAddressPostCode,
			@AgentAddressCountryGuid		= a_add_cr.Guid,
			@AgentContactDisplayName		= e.AgentContactDisplayName,
			@AgentContactDetailType			= e.AgentContactDetailType, 
			@AgentContactDetailTypeName		= e.AgentContactDisplayName,
			@AgentContactDetailTypeValue	= e.AgentContactDetailTypeValue,
			@FinanceAccountGuid				= f.Guid,
			@FinanceAddressGuid				= f_add.Guid,
			@FinanceContactGuid				= f_con.Guid,
			@FinanceName					= e.FinanceAccountName,
			@FinanceAddressNameNumber		= e.FinanceAddressNameNumber,
			@FinanceAddressLine1			= e.FinanceAddressLine1,
			@FinanceAddressLine2			= e.FinanceAddressLine2,
			@FinanceAddressLine3			= e.FinanceAddressLine3,
			@FinanceAddressTown				= e.FinanceTown,
			@FinanceAddressCountyGuid		= f_add_c.Guid,
			@FinanceAddressPostCode			= e.FinancePostCode,
			@FinanceAddressCountryGuid		= f_add_cr.Guid,
			@FinanceContactDisplayName		= e.FinanceContactDisplayName,
			@FinanceContactDetailType		= e.FinanceContactDetailType, 
			@FinanceContactDetailTypeName	= e.FinanceContactDisplayName,
			@FinanceContactDetailTypeValue	= e.FinanceContactDetailTypeValue,
			@QuotingUserGuid				= i.Guid,
			@IsClientFinanceAccount			= e.IsClientFinanceAccount,
			@ProjectGuid					= p.Guid,
			@ContractGuid                   = cc.Guid,
			@AgentContractGuid              = ac.Guid
	FROM	SSop.Enquiries			  AS e
	JOIN	SCore.OrganisationalUnits AS ou ON (ou.ID			  = e.OrganisationalUnitID)
	JOIN	SCore.Identities		  AS i ON (i.ID				  = e.CreatedByUserId)
	JOIN	SJob.Assets			  AS uprn ON (uprn.ID		  = e.PropertyId)
	JOIN	SCrm.Counties			  AS uprnc ON (uprnc.ID		  = e.PropertyCountyId)
	JOIN	SCrm.Countries			  AS uprncr ON (uprncr.ID	  = e.PropertyCountryId)
	JOIN	SCrm.Accounts			  AS c ON (c.ID				  = e.ClientAccountId)
	JOIN	SCrm.AccountAddresses	  AS c_add ON (c_add.ID		  = e.ClientAddressId)
	JOIN	SCrm.Counties			  AS c_add_c ON (c_add_c.ID	  = e.ClientAddressCountyId)
	JOIN	SCrm.Countries			  AS c_add_cr ON (c_add_cr.ID = e.ClientAddressCountryId)
	JOIN	SCrm.AccountContacts	  AS c_con ON (c_con.ID		  = e.ClientAccountContactId)
	JOIN	SCrm.Accounts			  AS a ON (a.ID				  = e.AgentAccountId)
	JOIN	SCrm.AccountAddresses	  AS a_add ON (a_add.ID		  = e.AgentAddressId)
	JOIN	SCrm.Counties			  AS a_add_c ON (a_add_c.ID	  = e.AgentCountyId)
	JOIN	SCrm.Countries			  AS a_add_cr ON (a_add_cr.ID = e.AgentCountryId)
	JOIN	SCrm.Accounts			  AS f ON (f.ID				  = e.FinanceAccountId)
	JOIN	SCrm.AccountAddresses	  AS f_add ON (f_add.ID		  = e.FinanceAddressId)
	JOIN	SCrm.Counties			  AS f_add_c ON (f_add_c.ID	  = e.FinanceCountyId)
	JOIN	SCrm.Countries			  AS f_add_cr ON (f_add_cr.ID = f_add_c.CountryID)
	JOIN	SCrm.AccountContacts	  AS f_con ON (f_con.ID		  = e.FinanceContactId)
	JOIN	SCrm.AccountContacts	  AS a_con ON (a_con.ID		  = e.AgentAccountContactId)
	JOIN	SSop.Projects			  AS p ON (p.ID				  = e.ProjectId)
	JOIN    SSop.Contracts            AS cc ON (e.ContractID      = cc.ID)
	JOIN    SSop.Contracts            AS ac ON (e.AgentContractID = ac.ID)
	WHERE	(e.Guid = @Guid);


	/* Convert new structure details */
	IF (@PropertyGuid = '00000000-0000-0000-0000-000000000000')
	BEGIN
		SET @PropertyGuid = NEWID ();

		DECLARE @GovUPRN NVARCHAR(20)	= N'';
		DECLARE @Lat DECIMAL(9,6)		= 0;
		DECLARE @Lon DECIMAL(9,6)		= 0;

		IF(@AssetJSONDetails <> N'')
			BEGIN

				
				SELECT @GovUPRN = value
      			FROM OPENJSON('["' + REPLACE(@AssetJSONDetails, '|', '","') + '"]')
      			WHERE [key] = 0

				SELECT @Lat = TRY_CONVERT(DECIMAL(9,6), value)
				FROM OPENJSON('["' + REPLACE(@AssetJSONDetails, '|', '","') + '"]')
				WHERE [key] = 1;

				SELECT @Lon = TRY_CONVERT(DECIMAL(9,6), value)
				FROM OPENJSON('["' + REPLACE(@AssetJSONDetails, '|', '","') + '"]')
				WHERE [key] = 2;

			END;
			
			

		EXEC SJob.AssetsUpsert @ParentAssetGuid = '00000000-0000-0000-0000-000000000000',		-- uniqueidentifier
								   @Name = N'',															-- nvarchar(100)
								   @Number = @PropertyNameNumber,										-- nvarchar(50)
								   @AddressLine1 = @PropertyAddressLine1,								-- nvarchar(50)
								   @AddressLine2 = @PropertyAddressLine2,								-- nvarchar(50)
								   @AddressLine3 = @PropertyAddressLine3,								-- nvarchar(50)
								   @Town = @PropertyTown,												-- nvarchar(50)
								   @CountyGuid = @PropertyCountyGuid,									-- nvarchar(50)
								   @Postcode = @PropertyPostCode,										-- nvarchar(50)
								   @CountryGuid = @PropertyCountryGuid,
								   @LocalAuthorityAccountGuid = '00000000-0000-0000-0000-000000000000', -- uniqueidentifier
								   @FireAuthorityAccountGuid = '00000000-0000-0000-0000-000000000000',	-- uniqueidentifier
								   @WaterAuthorityAccountGuid = '00000000-0000-0000-0000-000000000000', -- uniqueidentifier
								   @Latitude = @Lat,														-- decimal(9, 6)
								   @Longitude = @Lon,														-- decimal(9, 6)
								   @IsHighRiskBuilding = 0,
								   @IsComplexBuilding = 0,
								   @BuildingHeightInMetres = 0,
								   @OwnerAccountGuid = '00000000-0000-0000-0000-000000000000',
								   @Guid = @PropertyGuid,												-- uniqueidentifier
								   @GovernmentUPRN = @GovUPRN


		--Once we have created the asset record, clear the AssetJSON field on the enquiry (this is a hidden field by default, but just to be on the safe side).
		UPDATE SSop.Enquiries
		SET AssetJSONDetails = N''
		WHERE Guid = @Guid


	END;

	SELECT	@AccountStatusGuid = s.Guid
	FROM	SCrm.AccountStatus AS s
	WHERE	(s.Name = N'Prospect');

	/* Convert new client details */
	IF (@ClientAccountGuid = '00000000-0000-0000-0000-000000000000')
   AND	(@ClientName <> N'')
	BEGIN
		SET @ClientAccountGuid = NEWID ();

		EXEC SCrm.AccountsUpsert @Name = @ClientName,											-- nvarchar(250)
								 @Code = N'',													-- nvarchar(10)
								 @AccountStatusGuid = @AccountStatusGuid,						-- uniqueidentifier
								 @ParentAccountGuid = '00000000-0000-0000-0000-000000000000',	-- uniqueidentifier
								 @IsPurchaseLedger = 0,											-- bit
								 @IsSalesLedger = 1,											-- bit
								 @IsLocalAuthority = 0,											-- bit
								 @IsFireAuthority = 0,											-- bit
								 @IsWaterAuthority = 0,											-- bit
								 @RelationshipManagerUserGuid = @QuotingUserGuid,				-- uniqueidentifier
								 @CompanyRegistrationNumber = N'',								-- nvarchar(50)
								 @MainAccountContactGuid = '00000000-0000-0000-0000-000000000000',
								 @MainAccountAddressGuid = '00000000-0000-0000-0000-000000000000',
								 @Guid = @ClientAccountGuid,									-- uniqueidentifier
								 @DefaultCreditTermsGuid = '00000000-0000-0000-0000-000000000000',
								 @BillingInstruction = NULL; --Since it is a new Account record, we can set it to null
	END;

	

	IF (
		   @ClientAddressGuid = '00000000-0000-0000-0000-000000000000'
	   AND	@ClientAddressNameNumber <> N''
	   )
	BEGIN
		SET @ClientAddressGuid = NEWID ();

		EXEC SCrm.AddressUpsert @AddressNumber = 0,							-- int
								@Name = N'',								-- nvarchar(100)
								@Number = @ClientAddressNameNumber,			-- nvarchar(100)
								@AddressLine1 = @ClientAddressLine1,		-- nvarchar(255)
								@AddressLine2 = @ClientAddressLine2,		-- nvarchar(255)
								@AddressLine3 = @ClientAddressLine3,		-- nvarchar(255)
								@Town = @ClientAddressTown,					-- nvarchar(255)
								@CountyGuid = @ClientAddressCountyGuid,		-- uniqueidentifier
								@Postcode = @ClientAddressPostCode,			-- nvarchar(50)
								@CountryGuid = @ClientAddressCountryGuid,	-- uniqueidentifier
								@Guid = @ClientAddressGuid OUTPUT;			-- uniqueidentifier

		DECLARE @AccountAddressGuid UNIQUEIDENTIFIER = NEWID ();

		EXEC SCrm.AccountAddressesUpsert @AccountGuid = @ClientAccountGuid, -- uniqueidentifier
										 @AddressGuid = @ClientAddressGuid, -- uniqueidentifier
										 @Guid = @AccountAddressGuid;		-- uniqueidentifier

		SET @ClientAddressGuid = @AccountAddressGuid;

		IF (EXISTS
		 (
			 SELECT 1
			 FROM	SCrm.Accounts AS a
			 WHERE	(a.MainAccountAddressId < 0)
				AND (a.Guid					= @ClientAccountGuid)
		 )
		   )
		BEGIN
			UPDATE	a
			SET		a.MainAccountAddressId = aa.ID
			FROM	SCrm.Accounts		  AS a
			JOIN	SCrm.AccountAddresses AS aa ON (aa.AccountID = a.ID)
			WHERE	(a.Guid = @ClientAccountGuid);
		END;


		/*
			Create Contact and then Account Contact
		*/
		
		IF(@ClientContactDisplayName <> N'')
		BEGIN
		
			SET @ContactForClientGuid = NEWID();
			EXEC SCrm.ContactUpsert @FirstName = N'',
									@Surname = N'',
									@DisplayName = @ClientContactDisplayName,
									@IsPerson = 1,
									@PrimaryAccountGuid = '00000000-0000-0000-0000-000000000000',
									@PrimaryAddressGuid = '00000000-0000-0000-0000-000000000000',
									@TitleGuid = '00000000-0000-0000-0000-000000000000',
									@PositionGuid =  '00000000-0000-0000-0000-000000000000',
									@Initials = N'',
									@PostNominals = N'',
									@Guid = @ContactForClientGuid

			DECLARE @ContactDetailGuid UNIQUEIDENTIFIER = NEWID();
			DECLARE @ContactDetailTypeGuid UNIQUEIDENTIFIER;


			-- Get the GUID for the contact detail type.
			SELECT @ContactDetailTypeGuid = Guid
			FROM SCrm.ContactDetailTypes AS CDT
			WHERE (CDT.ID = @ClientContactDetailType)


			-- Create the contact detail for the contact.
			EXEC SCrm.ContactDetailUpsert @Name = @ClientContactDetailTypeName,           
										  @Value = @ClientContactDetailTypeValue,                
										  @ContactGuid = @ContactForClientGuid,      
										  @ContactDetailTypeGuid  = @ContactDetailTypeGuid,
										  @IsDefault = 0,           
										  @Guid = @ContactDetailGuid  
										  

			DECLARE @ClientAccountContactDetailGuid UNIQUEIDENTIFIER = NEWID();
			-- Add the contact to the account.
			EXEC SCrm.AccountContactsUpsert @AccountGuid = @ClientAccountGuid,
											@ContactGuid = @ContactForClientGuid,
											@PrimaryAccountAddressGuid = @AccountAddressGuid,
											@Guid = @ClientAccountContactDetailGuid

		END;
	END;


		


	IF (@IsClientFinanceAccount = 1)
	BEGIN
		SET @FinanceAccountGuid = @ClientAccountGuid;
		SET @FinanceAddressGuid = @ClientAddressGuid;
		SET @FinanceContactGuid = @ClientContactGuid;
	END;

	/* Convert new agent details */
	IF (@AgentAccountGuid = '00000000-0000-0000-0000-000000000000')
   AND	(@AgentName <> N'')
	BEGIN
		SET @AgentAccountGuid = NEWID ();

		EXEC SCrm.AccountsUpsert @Name = @AgentName,											-- nvarchar(250)
								 @Code = N'',													-- nvarchar(10)
								 @AccountStatusGuid = @AccountStatusGuid,						-- uniqueidentifier
								 @ParentAccountGuid = '00000000-0000-0000-0000-000000000000',	-- uniqueidentifier
								 @IsPurchaseLedger = 0,											-- bit
								 @IsSalesLedger = 1,											-- bit
								 @IsLocalAuthority = 0,											-- bit
								 @IsFireAuthority = 0,											-- bit
								 @IsWaterAuthority = 0,											-- bit
								 @RelationshipManagerUserGuid = @QuotingUserGuid,				-- uniqueidentifier
								 @CompanyRegistrationNumber = N'',								-- nvarchar(50)
								 @MainAccountAddressGuid = '00000000-0000-0000-0000-000000000000',
								 @MainAccountContactGuid = '00000000-0000-0000-0000-000000000000',
								 @Guid = @AgentAccountGuid,										-- uniqueidentifier
								 @DefaultCreditTermsGuid = '00000000-0000-0000-0000-000000000000',
								 @BillingInstruction = NULL; --Same as above --> Since it is new, it can be set to null.

	END;

	IF (
		   @AgentAddressGuid = '00000000-0000-0000-0000-000000000000'
	   AND	@AgentAddressNameNumber <> N''
	   )
	BEGIN
		SET @AgentAddressGuid = NEWID ();

		EXEC SCrm.AddressUpsert @AddressNumber = 0,							-- int
								@Name = N'',								-- nvarchar(100)
								@Number = @AgentAddressNameNumber,			-- nvarchar(100)
								@AddressLine1 = @AgentAddressLine1,			-- nvarchar(255)
								@AddressLine2 = @AgentAddressLine2,			-- nvarchar(255)
								@AddressLine3 = @AgentAddressLine3,			-- nvarchar(255)
								@Town = @AgentAddressTown,					-- nvarchar(255)
								@CountyGuid = @AgentAddressCountyGuid,		-- uniqueidentifier
								@Postcode = @AgentAddressPostCode,			-- nvarchar(50)
								@CountryGuid = @AgentAddressCountryGuid,	-- uniqueidentifier
								@Guid = @AgentAddressGuid OUTPUT;			-- uniqueidentifier

		DECLARE @AgentAccountAddressGuid UNIQUEIDENTIFIER = NEWID ();

		EXEC SCrm.AccountAddressesUpsert @AccountGuid = @AgentAccountGuid,	-- uniqueidentifier
										 @AddressGuid = @AgentAddressGuid,	-- uniqueidentifier
										 @Guid = @AgentAccountAddressGuid;	-- uniqueidentifier

		SET @AgentAddressGuid = @AgentAccountAddressGuid;

		IF (EXISTS
		 (
			 SELECT 1
			 FROM	SCrm.Accounts AS a
			 WHERE	(a.MainAccountAddressId < 0)
				AND (a.Guid					= @AgentAccountGuid)
		 )
		   )
		BEGIN
			UPDATE	a
			SET		a.MainAccountAddressId = aa.ID
			FROM	SCrm.Accounts		  AS a
			JOIN	SCrm.AccountAddresses AS aa ON (aa.AccountID = a.ID)
			WHERE	(a.Guid = @AgentAccountGuid);
		END;

		-- Create Contact and then Account Contact for Agent
		IF(@AgentContactDisplayName <> N'')
		BEGIN
		
			SET @ContactForAgentGuid = NEWID();
			EXEC SCrm.ContactUpsert @FirstName = N'',
									@Surname = N'',
									@DisplayName = @AgentContactDisplayName,
									@IsPerson = 1,
									@PrimaryAccountGuid = '00000000-0000-0000-0000-000000000000',
									@PrimaryAddressGuid = '00000000-0000-0000-0000-000000000000',
									@TitleGuid = '00000000-0000-0000-0000-000000000000',
									@PositionGuid =  '00000000-0000-0000-0000-000000000000',
									@Initials = N'',
									@PostNominals = N'',
									@Guid = @ContactForAgentGuid

			SET @AgentContactDetailGuid = NEWID();
			DECLARE @AgentContactDetailTypeGuid UNIQUEIDENTIFIER;


			-- Get the GUID for the contact detail type.
			SELECT @AgentContactDetailTypeGuid = Guid
			FROM SCrm.ContactDetailTypes AS CDT
			WHERE (CDT.ID = @AgentContactDetailType)


			-- Create the contact detail for the contact.
			EXEC SCrm.ContactDetailUpsert @Name = @AgentContactDetailTypeName,           
										  @Value = @AgentContactDetailTypeValue,                
										  @ContactGuid = @ContactForAgentGuid,      
										  @ContactDetailTypeGuid  = @AgentContactDetailTypeGuid,
										  @IsDefault = 0,           
										  @Guid = @AgentContactDetailGuid  
										  

			DECLARE @AgentAccountContactDetailGuid UNIQUEIDENTIFIER = NEWID();
			-- Add the contact to the account.
			EXEC SCrm.AccountContactsUpsert @AccountGuid = @AgentAccountGuid,
											@ContactGuid = @ContactForAgentGuid,
											@PrimaryAccountAddressGuid = @AgentAccountAddressGuid,
											@Guid = @AgentAccountContactDetailGuid

		END;
	END;

		

	/* Convert new finance details */
	IF (@FinanceAccountGuid = '00000000-0000-0000-0000-000000000000')
   AND	(@FinanceName <> N'')
   AND	(@IsClientFinanceAccount = 0)
	BEGIN
		SET @FinanceAccountGuid = NEWID ();

		EXEC SCrm.AccountsUpsert @Name = @FinanceName,											-- nvarchar(250)
								 @Code = N'',													-- nvarchar(10)
								 @AccountStatusGuid = @AccountStatusGuid,						-- uniqueidentifier
								 @ParentAccountGuid = '00000000-0000-0000-0000-000000000000',	-- uniqueidentifier
								 @IsPurchaseLedger = 0,											-- bit
								 @IsSalesLedger = 1,											-- bit
								 @IsLocalAuthority = 0,											-- bit
								 @IsFireAuthority = 0,											-- bit
								 @IsWaterAuthority = 0,											-- bit
								 @RelationshipManagerUserGuid = @QuotingUserGuid,				-- uniqueidentifier
								 @CompanyRegistrationNumber = N'',								-- nvarchar(50)
								 @MainAccountAddressGuid = '00000000-0000-0000-0000-000000000000',
								 @MainAccountContactGuid = '00000000-0000-0000-0000-000000000000',
								 @Guid = @FinanceAccountGuid,									-- uniqueidentifier
								 @DefaultCreditTermsGuid = '00000000-0000-0000-0000-000000000000',
								 @BillingInstruction = NULL; --Same as above -> New record can be set to null
	END;

	IF (
		   @FinanceAddressGuid = '00000000-0000-0000-0000-000000000000'
	   AND	@FinanceAddressNameNumber <> N''
	   AND	(@IsClientFinanceAccount = 0)
	   )
	BEGIN
		SET @FinanceAddressGuid = NEWID ();

		EXEC SCrm.AddressUpsert @AddressNumber = 0,							-- int
								@Name = N'',								-- nvarchar(100)
								@Number = @FinanceAddressNameNumber,		-- nvarchar(100)
								@AddressLine1 = @FinanceAddressLine1,		-- nvarchar(255)
								@AddressLine2 = @FinanceAddressLine2,		-- nvarchar(255)
								@AddressLine3 = @FinanceAddressLine3,		-- nvarchar(255)
								@Town = @FinanceAddressTown,				-- nvarchar(255)
								@CountyGuid = @FinanceAddressCountyGuid,	-- uniqueidentifier
								@Postcode = @FinanceAddressPostCode,		-- nvarchar(50)
								@CountryGuid = @FinanceAddressCountryGuid,	-- uniqueidentifier
								@Guid = @FinanceAddressGuid OUTPUT;			-- uniqueidentifier

		DECLARE @FinanceAccountAddressGuid UNIQUEIDENTIFIER = NEWID ();
		
		
		--EXEC SCrm.AddressUpsert 
		--						@AccountGuid = @FinanceAccountGuid, -- uniqueidentifier
		--						@AddressGuid = @FinanceAddressGuid, -- uniqueidentifier
		--						@Guid = @FinanceAccountAddressGuid; -- uniqueidentifier

		EXEC SCrm.AccountAddressesUpsert 
								@AccountGuid = @FinanceAccountGuid, -- uniqueidentifier
								@AddressGuid = @FinanceAddressGuid, -- uniqueidentifier
								@Guid = @FinanceAccountAddressGuid; -- uniqueidentifier

		

		SET @FinanceAddressGuid = @FinanceAccountAddressGuid;

		IF (EXISTS
		 (
			 SELECT 1
			 FROM	SCrm.Accounts AS a
			 WHERE	(a.MainAccountAddressId < 0)
				AND (a.Guid					= @FinanceAccountGuid)
		 )
		   )
		BEGIN
			UPDATE	a
			SET		a.MainAccountAddressId = aa.ID
			FROM	SCrm.Accounts		  AS a
			JOIN	SCrm.AccountAddresses AS aa ON (aa.AccountID = a.ID)
			WHERE	(a.Guid = @FinanceAccountGuid);
		END;

		/*
			Create Contact and then Account Contact for Agent
		*/
		
		IF(@FinanceContactDisplayName <> N'')
		BEGIN
		
			SET @ContactForFinanceGuid = NEWID();
			EXEC SCrm.ContactUpsert @FirstName = N'',
									@Surname = N'',
									@DisplayName = @FinanceContactDisplayName,
									@IsPerson = 1,
									@PrimaryAccountGuid = '00000000-0000-0000-0000-000000000000',
									@PrimaryAddressGuid = '00000000-0000-0000-0000-000000000000',
									@TitleGuid = '00000000-0000-0000-0000-000000000000',
									@PositionGuid =  '00000000-0000-0000-0000-000000000000',
									@Initials = N'',
									@PostNominals = N'',
									@Guid = @ContactForFinanceGuid

			SET @FinanceContactDetailGuid = NEWID();
			DECLARE @FinanceContactDetailTypeGuid UNIQUEIDENTIFIER;


			-- Get the GUID for the contact detail type.
			SELECT @FinanceContactDetailTypeGuid = Guid
			FROM SCrm.ContactDetailTypes AS CDT
			WHERE (CDT.ID = @FinanceContactDetailType)


			-- Create the contact detail for the contact.
			EXEC SCrm.ContactDetailUpsert @Name = @FinanceContactDetailTypeName,           
										  @Value = @FinanceContactDetailTypeValue,                
										  @ContactGuid = @ContactForFinanceGuid,      
										  @ContactDetailTypeGuid  = @FinanceContactDetailTypeGuid,
										  @IsDefault = 0,           
										  @Guid = @FinanceContactDetailGuid  
										  

			DECLARE @FinanceAccountContactDetailGuid UNIQUEIDENTIFIER = NEWID();
			-- Add the contact to the account.
			EXEC SCrm.AccountContactsUpsert @AccountGuid = @FinanceAccountGuid,
											@ContactGuid = @ContactForFinanceGuid,
											@PrimaryAccountAddressGuid = @FinanceAccountAddressGuid,
											@Guid = @FinanceAccountContactDetailGuid

		END;
	END;

		

	/* Build a consolidated list of quotes to create  */
	DECLARE @QuotesToCreate TABLE
		(
			ID INT NOT NULL PRIMARY KEY,
			Guid UNIQUEIDENTIFIER NOT NULL DEFAULT NEWID (),
			OrganisationalUnitGuid UNIQUEIDENTIFIER NOT NULL,
			EnquiryGuid UNIQUEIDENTIFIER NOT NULL,
			DescriptionOfWorks NVARCHAR(4000) NOT NULL,
			JobTypeName NVARCHAR(100) NOT NULL,
			JobTypeId	INT NOT NULL, 
			SendInfoToClient BIT NOT NULL,
			SendInfoToAgent BIT NOT NULL,
			ExternalReference NVARCHAR(50) NOT NULL,
			ValueOfWork DECIMAL(19, 2) NOT NULL,
			CurrentStageGuid UNIQUEIDENTIFIER NOT NULL,
			AppointmentStageGuid UNIQUEIDENTIFIER NOT NULL,
			IsSubjectToNDA BIT NOT NULL,
			EnquiryServiceGuid UNIQUEIDENTIFIER NOT NULL
		);

	INSERT	@QuotesToCreate
		 (ID,
		  OrganisationalUnitGuid,
		  EnquiryGuid,
		  DescriptionOfWorks,
		  JobTypeName,
		  JobTypeId,
		  SendInfoToClient,
		  SendInfoToAgent,
		  ExternalReference,
		  ValueOfWork,
		  CurrentStageGuid,
		  AppointmentStageGuid,
		  IsSubjectToNDA,
		  EnquiryServiceGuid)
	SELECT	es.ID,
			ou.Guid,
			@Guid,
			e.DescriptionOfWorks,
			jt.Name,
			jt.ID, 
			e.SendInfoToClient,
			e.SendInfoToAgent,
			e.ExternalReference,
			e.ValueOfWork,
			cs.Guid,
			aps.Guid,
			e.IsSubjectToNDA,
			es.Guid
	FROM	SSop.EnquiryServices	  AS es
	JOIN	SSop.Enquiries			  AS e ON (e.ID		= es.EnquiryId)
	JOIN	SJob.JobTypes			  AS jt ON (jt.ID	= es.JobTypeId)
	JOIN	SCore.OrganisationalUnits AS ou ON (ou.ID	= jt.OrganisationalUnitID)
	JOIN	SJob.RibaStages			  AS cs ON (cs.ID	= e.CurrentProjectRibaStageID)
	JOIN	SJob.RibaStages			  AS aps ON (aps.ID = es.StartRibaStageId)
	WHERE	(e.Guid = @Guid)
		AND (es.RowStatus NOT IN (0, 254))
		AND (NOT EXISTS
		(
			SELECT	1
			FROM	SSop.Quotes AS q
			WHERE	(q.EnquiryServiceID = es.ID)
				AND (q.RowStatus NOT IN (0, 254))
		)
			);

	IF NOT EXISTS
	 (
		 SELECT 1
		 FROM	@QuotesToCreate
	 )
	BEGIN
		;
		THROW 60000, N'There were no quotes to create', 1;
	END;

	/*
		  Loop through the list of Quotes executing QuotesUpsert
	  */
	DECLARE @CreatedDateTime		DATETIME2 = GETUTCDATE (),
			@ExpiryDate				DATETIME2 = DATEADD (	MONTH,
															6,
															GETUTCDATE ()
														),
			@OrganisationalUnitGuid UNIQUEIDENTIFIER,
			@DescriptionOfWorks		NVARCHAR(4000),
			@QuoteGuid				UNIQUEIDENTIFIER,
			@MaxID					INT,
			@CurrentId				INT,
			@ExternalReference		NVARCHAR(50),
			@CurrentStageGuid		UNIQUEIDENTIFIER,
			@AppointmentStageGuid	UNIQUEIDENTIFIER,
			@EnquiryServiceGuid		UNIQUEIDENTIFIER,
			@IsSubjectToNDA         BIT,
			@MarketGuid				UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
			@SectorGuid				UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
			@JobTypeGuid			UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
			@DataClassificationGuid UNIQUEIDENTIFIER = '31E24091-52B4-480E-9A85-7052F614567A',
			@SecurityClassificationGuid UNIQUEIDENTIFIER = 'B4EF7A4D-454B-4C4B-AF3D-5996312FD038';

	SELECT @MarketGuid = Guid FROM SCore.Markets WHERE Name LIKE N'%UK%'


	SELECT	@MaxID	   = MAX (ID),
			@CurrentId = 0
	FROM	@QuotesToCreate;

	

	WHILE (@CurrentId < @MaxID)
	BEGIN
		SELECT TOP (1)
			@CurrentId              = q.ID,
			@DescriptionOfWorks     = q.JobTypeName + N' -- ' + q.DescriptionOfWorks,
			@QuoteGuid              = q.Guid,
			@OrganisationalUnitGuid = q.OrganisationalUnitGuid,
			@ExternalReference      = q.ExternalReference,
			@CurrentStageGuid       = q.CurrentStageGuid,
			@AppointmentStageGuid   = q.AppointmentStageGuid,
			@EnquiryServiceGuid     = q.EnquiryServiceGuid,
			@IsSubjectToNDA         = q.IsSubjectToNDA,
			@JobTypeId              = q.JobTypeId
		FROM @QuotesToCreate AS q
		WHERE q.ID > @CurrentId
		ORDER BY q.ID;

		SELECT @JobTypeGuid = jt.Guid
		FROM SJob.JobTypes AS jt
		WHERE jt.ID = @JobTypeId
		  AND jt.RowStatus NOT IN (0,254);

		IF (@JobTypeGuid IS NULL OR @JobTypeGuid = '00000000-0000-0000-0000-000000000000')
		BEGIN
			;THROW 60000, N'Could not resolve Job Type for quote creation.', 1;
		END;

		EXEC SSop.QuotesUpsert @OrganisationalUnitGuid = @OrganisationalUnitGuid,		-- uniqueidentifier
							   @QuotingUserGuid = @QuotingUserGuid,						-- uniqueidentifier
							   @ContractGuid = @ContractGuid,	-- uniqueidentifier
							   @Date = @CreatedDateTime,								-- date
							   @Overview = @DescriptionOfWorks,							-- nvarchar(max)
							   @ExpiryDate = @ExpiryDate,								-- date
							   @DateSent = NULL,										-- date
							   @DateAccepted = NULL,									-- date
							   @DateRejected = NULL,									-- date
							   @RejectionReason = N'',									-- nvarchar(max)
							   @FeeCap = 0,												-- decimal(19, 2)
							   @IsFinal = 0,
							   @ExternalReference = @ExternalReference,
							   @QuotingConsultantGuid = @QuotingUserGuid,
							   @AppointmentFromRibaStageGuid = @AppointmentStageGuid,
							   @CurrentStageGuid = @CurrentStageGuid,
							   @DeadDate = NULL,
							   @EnquiryServiceGuid = @EnquiryServiceGuid,
							   @ProjectGuid = @ProjectGuid,
							   @Guid = @QuoteGuid,
							   @JobType = @JobTypeGuid,	
							   @DescriptionOfWorks = @DescriptionOfWorks,
							   @DeclinedToQuoteReason = N'',
							   @ExclusionsAndLimitations = N'',
							   @IsSubjectToNDA = @IsSubjectToNDA,
							   @AgentContractGuid = @AgentContractGuid,
							   @SectorGuid = @SectorGuid,
							   @MarketGuid = @MarketGuid,
							   @DataClassificationGuid = @DataClassificationGuid,
							   @SecurityClassificationGuid = @SecurityClassificationGuid;
							   
							  
	END;

	DECLARE @PropertyID		  INT,
			@ClientID		  INT,
			@AgentID		  INT,
			@FinanceID		  INT,
			@ClientAddressID  INT,
			@AgentAddressID	  INT,
			@FinanceAddressID INT,
			@ClientContactID  INT,
			@AgentContactID   INT,
			@FinanceContactID INT;

	SELECT	@PropertyID = p.ID
	FROM	SJob.Assets AS p
	WHERE	(p.Guid = @PropertyGuid);

	SELECT	@ClientID = a.ID
	FROM	SCrm.Accounts AS a
	WHERE	(a.Guid = @ClientAccountGuid);

	SELECT	@ClientAddressID = a.ID
	FROM	SCrm.AccountAddresses AS a
	WHERE	(a.Guid = @ClientAddressGuid);

	SELECT	@AgentID = a.ID
	FROM	SCrm.Accounts AS a
	WHERE	(a.Guid = @AgentAccountGuid);

	SELECT	@AgentAddressID = a.ID
	FROM	SCrm.AccountAddresses AS a
	WHERE	(a.Guid = @AgentAddressGuid);

	SELECT	@FinanceID = a.ID
	FROM	SCrm.Accounts AS a
	WHERE	(a.Guid = @FinanceAccountGuid);

	SELECT	@FinanceAddressID = a.ID
	FROM	SCrm.AccountAddresses AS a
	WHERE	(a.Guid = @FinanceAddressGuid);


	


	SELECT @ClientContactID = ID
	FROM SCrm.AccountContacts
	WHERE Guid = @ClientAccountContactDetailGuid;

	SELECT @AgentContactID = ID
	FROM SCrm.AccountContacts
	WHERE Guid = @AgentAccountContactDetailGuid;

	SELECT @FinanceContactID = ID
	FROM SCrm.AccountContacts
	WHERE Guid = @FinanceAccountContactDetailGuid;


	

	/* Update the Enquiry with the created records */
	UPDATE	SSop.Enquiries
	SET		PropertyId = @PropertyID,
			ClientAccountId = @ClientID,
			AgentAccountId = @AgentID,
			FinanceAccountId = @FinanceID,
			ClientAddressId = @ClientAddressID,
			AgentAddressId = @AgentAddressID,
			FinanceAddressId = @FinanceAddressID,
			EnterNewClientDetails = 0,
			EnterNewAgentDetails = 0,
			EnterNewFinanceDetails = 0,
			EnterNewStructureDetails = 0
	WHERE	(Guid = @Guid);

	-- Set the client contact, finance contact, and agent contact.
	IF(@ClientContactDisplayName <> N'')
	BEGIN
		UPDATE SSop.Enquiries
		SET ClientAccountContactId = @ClientContactID
		WHERE	(Guid = @Guid);
	END;

	IF(@AgentContactDisplayName <> N'')
	BEGIN
		UPDATE SSop.Enquiries
		SET AgentAccountContactId = @AgentContactID
		WHERE	(Guid = @Guid);
	END;

	IF(@FinanceContactDisplayName <> N'')
	BEGIN
		UPDATE SSop.Enquiries
		SET FinanceContactId = @FinanceContactID
		WHERE	(Guid = @Guid);
	END;

END;
GO
GO

/* Deploy View SSop.Quote_MergeInfo using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Views\SSop.Quote_MergeInfo.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create view [SSop].[Quote_MergeInfo]')
GO
PRINT (N'Create view [SSop].[Quote_MergeInfo]')
GO

CREATE OR ALTER VIEW [SSop].[Quote_MergeInfo]
AS
SELECT		q.ID,
			q.RowStatus,
			q.RowVersion,
			q.Guid,
			q.Number																					 AS QuoteNumber,
			q.DescriptionOfWorks																		 AS QuoteOverview,
			q.Date																						 AS QuoteDate,
			q.FeeCap,
																																	/* UPRN */
			uprn.Number																					 AS UPRN,
			uprn.AddressLine1																			 AS PropertyAddressLine1,	-- was PropertyAddress1
			uprn.AddressLine2																			 AS PropertyAddressLine2,	-- was PropertyAddress2
			uprn.AddressLine3																			 AS PropertyAddressLine3,	-- was PropertyAddress3
			uprn.Town																					 AS PropertyTown,
			uprnc.Name																					 AS PropertyCounty,
			uprn.Postcode																				 AS PropertyPostcode,
			uprn.FormattedAddressComma																	 AS PropertyAddress,
			uprn.FormattedAddressCR																		 AS PropertyAddressBlock,
			COALESCE (	 uprn.Name + ' ',
						 ''
					 ) + COALESCE (	  uprn.Number + ' ',
									  ''
								  ) + uprn.AddressLine1													 AS PropertyShortAddress,
																																	/* Client */
			cacc.Name																					 AS ClientName,				-- was [Label] or [Title]
			cacc.CompanyRegistrationNumber																 AS ClientCompanyRegNo,
			cadd.AddressLine1																			 AS ClientAddressLine1,		-- was ClientAddress1
			cadd.AddressLine2																			 AS ClientAddressLine2,		-- was ClientAddress2
			cadd.AddressLine3																			 AS ClientAddressLine3,		-- was ClientAddress3
			cadd.Town																					 AS ClientTown,
			caddc.Name																					 AS ClientCounty,
			cadd.Postcode																				 AS ClientPostcode,
			cadd.FormattedAddressComma																	 AS ClientAddress,			-- was AddressClient
			cadd.FormattedAddressCR																		 AS ClientAddressBlock,
			ccon.DisplayName																			 AS ClientContactName,
			ccon.FirstName																				 AS ClientFirstName,
			ccon.Surname																				 AS ClientSurname,
			ccon.Email																					 AS ClientEmail,
			ccon.Phone																					 AS ClientPhone,
			ccon.Mobile																					 AS ClientMobile,
			CASE
				WHEN q.SendInfoToClient = 1 THEN cacc.Name
				ELSE aacc.Name
			END																							 AS RecipientName,			-- was [Label] or [Title]
			CASE
				WHEN q.SendInfoToClient = 1 THEN cacc.CompanyRegistrationNumber
				ELSE aacc.CompanyRegistrationNumber
			END																							 AS RecipientCompanyRegNo,
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.AddressLine1
				ELSE aadd.AddressLine1
			END																							 AS RecipientAddressLine1,	-- was ClientAddress1
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.AddressLine2
				ELSE aadd.AddressLine2
			END																							 AS RecipientAddressLine2,	-- was ClientAddress2
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.AddressLine3
				ELSE aadd.AddressLine3
			END																							 AS RecipientAddressLine3,	-- was ClientAddress3
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.Town
				ELSE aadd.Town
			END																							 AS RecipientTown,
			CASE
				WHEN q.SendInfoToClient = 1 THEN caddc.Name
				ELSE aaddc.Name
			END																							 AS RecipientCounty,
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.Postcode
				ELSE aadd.Postcode
			END																							 AS RecipientPostcode,
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.FormattedAddressComma
				ELSE aadd.FormattedAddressComma
			END																							 AS RecipientAddress,		-- was AddressClient
			CASE
				WHEN q.SendInfoToClient = 1 THEN cadd.FormattedAddressCR
				ELSE aadd.FormattedAddressCR
			END																							 AS RecipientAddressBlock,
			CASE
				WHEN q.SendInfoToClient = 1 THEN ccon.DisplayName
				ELSE acon.DisplayName
			END																							 AS RecipientContactName,
			CASE
				WHEN q.SendInfoToClient = 1 THEN ccon.FirstName
				ELSE acon.FirstName
			END																							 AS RecipientFirstName,
			CASE
				WHEN q.SendInfoToClient = 1 THEN ccon.Surname
				ELSE ccon.Surname
			END																							 AS RecipientSurname,
			CASE
				WHEN q.SendInfoToClient = 1 THEN ccon.Email
				ELSE ccon.Email
			END																							 AS RecipientEmail,
			CASE
				WHEN q.SendInfoToClient = 1 THEN ccon.Phone
				ELSE ccon.Phone
			END																							 AS RecipientPhone,
			CASE
				WHEN q.SendInfoToClient = 1 THEN ccon.Mobile
				ELSE ccon.Mobile
			END																							 AS RecipientMobile,

																																	/* Company */
			offa.Name																					 AS OfficialName,
			offa.AddressLine1																			 AS OfficialAddressLine1,
			offa.AddressLine2																			 AS OfficialAddressLine2,
			offa.AddressLine3																			 AS OfficialAddressLine3,
			offa.Town																					 AS OfficialTown,
			offac.Name																					 AS OfficialCounty,
			offa.Postcode																				 AS OfficialPostcode,
			offcon.Email																				 AS OfficialEmail,
			offcon.Phone																				 AS OfficialPhone,
			offcon.Mobile																				 AS OfficialMobile,
																																	/* Fee Drawdown*/
			DrawDown.Stage1Net,
			DrawDown.Stage2Net,
			DrawDown.Stage3Net,
			DrawDown.Stage4Net,
			DrawDown.Stage5Net,
			DrawDown.Stage6Net,
			DrawDown.Stage7Net,
			DrawDown.PreConstruction,
			DrawDown.Construction,
			DrawDown.Stage1Net + DrawDown.Stage2Net + DrawDown.Stage3Net + DrawDown.Stage4Net + DrawDown.Stage5Net
			+ DrawDown.Stage6Net + DrawDown.Stage7Net + DrawDown.PreConstruction + DrawDown.Construction AS TotalNetFees,

																																	/* Quoting User */
			quconm.Email																				 AS QuotingUserEmail,
			qu.FullName																					 AS QuotingUserName,
			qu.FullName + N' ' + COALESCE (	  qucon.PostNominals,
											  ''
										  )																 AS QuotingUserPostNominals,
			qucon.Initials																				 AS QuotingUserInitials,
			qu.JobTitle																					 AS QuotingUserJobTitle,
			qcconm.Email																				 AS QuotingConsultantEmail,
			qc.FullName																					 AS QuotingConsultantName,
			qc.FullName + N' ' + COALESCE (	  qccon.PostNominals,
											  ''
										  )																 AS QuotingConsultantPostNominals,
			qccon.Initials																				 AS QuotingConsultantInitials,
			qc.JobTitle																					 AS QuotingConsultantJobTitle,

			aacc.Name				AS AgentAccountName,
			aacon.DisplayName		AS AgentContact,
			aaconadd.AddressLine1   AS AgentAddressLineOne,
			aaconadd.AddressLine2   AS AgentAddressLineTwo,
			aaconadd.AddressLine3   AS AgentAddressLineThree,
			aaconadd.Postcode		AS AgentPostcode,
		    
			cacc.Name				AS ClientAccountName,
			cacon.DisplayName       AS ClientContact,
			caconadd.AddressLine1   AS ClientAddressLineOne,
			caconadd.AddressLine2   AS ClientAddressLineTwo,
			caconadd.AddressLine3   AS ClientAddressLineThree
		


FROM		SSop.Quotes				  AS q
JOIN		SSop.EnquiryServices	  AS es ON (es.ID = q.EnquiryServiceID)
JOIN		SSop.Enquiries			  AS e ON (e.ID = es.EnquiryId)
JOIN		SCore.OrganisationalUnits AS ou ON (ou.ID = q.OrganisationalUnitID)
JOIN		SCrm.Contact_MergeInfo	  AS offcon ON (offcon.ID = ou.OfficialContactId)
JOIN		SCrm.Addresses			  AS offa ON (offa.ID = ou.OfficialAddressId)
JOIN		SCrm.Counties			  AS offac ON (offac.ID = offa.CountyID)
JOIN		SJob.Assets			  AS uprn ON (uprn.ID = e.PropertyId)
JOIN		SCrm.Counties			  AS uprnc ON (uprnc.ID = uprn.CountyId)
JOIN		SCrm.Accounts			  AS cacc ON (cacc.ID = e.ClientAccountId)
JOIN		SCrm.AccountAddresses	  AS caad ON (caad.ID = e.ClientAddressId)
JOIN		SCrm.Addresses			  AS cadd ON (cadd.ID = caad.AddressID)
JOIN		SCrm.AccountContacts	  AS cac ON (cac.ID = e.ClientAccountContactId)
JOIN		SCrm.Contact_MergeInfo	  AS ccon ON (ccon.ID = cac.ContactID)
JOIN		SCrm.Counties			  AS caddc ON (caddc.ID = cadd.CountyID)
JOIN		SCore.Identities		  AS qu ON (qu.ID = q.QuotingUserId)
JOIN		SCrm.Accounts			  AS aacc ON (aacc.ID = e.AgentAccountId)
JOIN		SCrm.AccountAddresses	  AS aaad ON (aaad.ID = e.AgentAddressId)
JOIN		SCrm.Addresses			  AS aadd ON (aadd.ID = aaad.AddressID)
JOIN		SCrm.AccountContacts	  AS aac ON (aac.ID = e.AgentAccountContactId)
JOIN		SCrm.Contact_MergeInfo	  AS acon ON (acon.ID = aac.ContactID)
JOIN		SCrm.Counties			  AS aaddc ON (aaddc.ID = aadd.CountyID)
LEFT JOIN	SCrm.Contacts			  AS qucon ON (qucon.ID = qu.ContactId)
LEFT JOIN	SCrm.Contact_MergeInfo	  AS quconm ON (quconm.ID = qucon.ID)
JOIN		SCore.Identities		  AS qc ON (qc.ID = q.QuotingConsultantId)
LEFT JOIN	SCrm.Contacts			  AS qccon ON (qccon.ID = qc.ContactId)
LEFT JOIN	SCrm.Contact_MergeInfo	  AS qcconm ON (qcconm.ID = qccon.ID)
JOIN        SCrm.Contacts	  AS aacon ON (aacon.ID = aac.ContactID)
JOIN		SCrm.Addresses    AS aaconadd ON (aaconadd.ID = aaad.AddressID)
JOIN        SCrm.Contacts	  AS cacon ON (cacon.ID = cac.ContactID)
JOIN		SCrm.Addresses    AS caconadd ON (caconadd.ID = caad.AddressID)
OUTER APPLY
			(
				SELECT	ID,
						ISNULL (   [1],
								   0
							   ) AS Stage1Net,
						ISNULL (   [2],
								   0
							   ) AS Stage2Net,
						ISNULL (   [3],
								   0
							   ) AS Stage3Net,
						ISNULL (   [4],
								   0
							   ) AS Stage4Net,
						ISNULL (   [5],
								   0
							   ) AS Stage5Net,
						ISNULL (   [6],
								   0
							   ) AS Stage6Net,
						ISNULL (   [7],
								   0
							   ) AS Stage7Net,
						ISNULL (   [99],
								   0
							   ) AS PreConstruction,
						ISNULL (   [999],
								   0
							   ) AS Construction
				FROM
						(
							SELECT	ID,
									Stage,
									Quoted
							FROM	SSop.tvf_QuoteFeeDrawdown (	  q.QuotingUserId,
																  q.Guid
															  )
						) AS d
				PIVOT
					(
						MIN(Quoted)
						FOR Stage IN ([1], [2], [3], [4], [5], [6], [7], [99], [999])
					) AS qfd
			)						  AS DrawDown;
GO
GO

/* Deploy StoredProcedure SSop.QuotesDuplicate using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SSop.QuotesDuplicate.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SSop].[QuotesDuplicate]')
GO
PRINT (N'Create procedure [SSop].[QuotesDuplicate]')
GO




CREATE OR ALTER PROCEDURE [SSop].[QuotesDuplicate] @SourceGuid UNIQUEIDENTIFIER,
									 @TargetGuid UNIQUEIDENTIFIER
AS
BEGIN

	DECLARE @SourceID INT,
			@ID		  INT,
			@IsInsert BIT;

	SELECT	@SourceID = ID
	FROM	SSop.Quotes
	WHERE	(Guid = @SourceGuid);

	IF (@@ROWCOUNT > 1)
	BEGIN
		;
		THROW 60000, N'Invalid source Quote', 1;
	END;

	EXEC SCore.UpsertDataObject @Guid = @TargetGuid,
								@SchemeName = N'SSop',
								@ObjectName = N'Quotes',
								@IncludeDefaultSecurity = 1,
								@IsInsert = @IsInsert;

	INSERT	SSop.Quotes
		 (RowStatus,
		  Guid,
		  OrganisationalUnitID,
		  QuotingUserId,
		  Number,
		  UprnId,
		  ClientAccountId,
		  ClientAddressId,
		  ClientContactId,
		  ContractID,
		  Date,
		  Overview,
		  ExpiryDate,
		  QuoteSourceId,
		  IsSubjectToNDA,
		  AgentAccountId,
		  AgentAddressId,
		  AgentContactId,
		  ExternalReference,
		  FeeCap,
		  EnquiryServiceID,
		  ProjectId,
		  DescriptionOfWorks,
		  QuotingConsultantId,
		  ExclusionsAndLimitations,
		  JobTypeId)
	SELECT	0,
			@TargetGuid,
			q.OrganisationalUnitID,
			q.QuotingUserId,
			N'0',
			q.UprnId,
			q.ClientAccountId,
			q.ClientAddressId,
			q.ClientContactId,
			q.ContractID,
			GETDATE (),
			q.Overview,
			DATEADD (	MONTH,
						6,
						GETDATE ()
					),
			q.QuoteSourceId,
			q.IsSubjectToNDA,
			q.AgentAccountId,
			q.AgentAddressId,
			q.AgentContactId,
			q.ExternalReference,
			q.FeeCap,
			q.EnquiryServiceID,
			q.ProjectId,
			q.DescriptionOfWorks,
			q.QuotingConsultantId,
			q.ExclusionsAndLimitations,
			q.JobTypeId
	FROM	SSop.Quotes AS q
	WHERE	(q.ID = @SourceID);

	SELECT	@ID = SCOPE_IDENTITY ();



	-- Build the collection of items to duplicate. 
	DECLARE @QuoteItems SCore.TwoGuidUniqueList;

	INSERT	@QuoteItems
		 (GuidValue, GuidValueTwo)
	SELECT	qi.Guid,
			NEWID ()
	FROM	SSop.QuoteItems AS qi
	WHERE	(qi.QuoteId = @SourceID) --CBLD-613
		AND (qi.RowStatus NOT IN (0, 254));


	-- Build the collection of payment stages to duplicate
	DECLARE @QuotePaymentStages SCore.TwoGuidUniqueList;

	INSERT	@QuotePaymentStages --RETURNS NOTHING
		 (GuidValue, GuidValueTwo)
	SELECT	qps.Guid,
			NEWID ()
	FROM	SSop.QuotePaymentStages AS qps
	WHERE	(qps.QuoteId = @SourceID)
		AND (qps.RowStatus NOT IN (0, 254));


	-- Build the collection of quote memos
	DECLARE @QuoteMemos SCore.TwoGuidUniqueList;

	INSERT	@QuoteMemos --RETURNS NOTHING
		 (GuidValue, GuidValueTwo)
	SELECT	qm.Guid,
			NEWID ()
	FROM	SSop.QuoteMemos AS qm
	WHERE	(qm.QuoteID = @SourceID)
		AND (qm.RowStatus NOT IN (0, 254));

	-- Create the data objects. 
	DECLARE @NewGuidList SCore.GuidUniqueList;


	INSERT	@NewGuidList
		 (GuidValue)
	SELECT	GuidValueTwo
	FROM	@QuoteItems;

	EXEC SCore.DataObjectBulkUpsert @GuidList = @NewGuidList,		-- GuidUniqueList
									@SchemeName = N'SSop',			-- nvarchar(255)
									@ObjectName = N'QuoteItems',	-- nvarchar(255)
									@IsInsert = @IsInsert OUTPUT;	-- bit	

	DELETE	FROM @NewGuidList;
	INSERT	@NewGuidList
		 (GuidValue)
	SELECT	GuidValueTwo
	FROM	@QuotePaymentStages;

	EXEC SCore.DataObjectBulkUpsert @GuidList = @NewGuidList,				-- GuidUniqueList
									@SchemeName = N'SSop',					-- nvarchar(255)
									@ObjectName = N'QuotePaymentStages',	-- nvarchar(255)
									@IsInsert = @IsInsert OUTPUT;			-- bit	

	DELETE	FROM @NewGuidList;
	INSERT	@NewGuidList
		 (GuidValue)
	SELECT	qm.GuidValueTwo
	FROM	@QuoteMemos AS qm;

	EXEC SCore.DataObjectBulkUpsert @GuidList = @NewGuidList,		-- GuidUniqueList
									@SchemeName = N'SSop',			-- nvarchar(255)
									@ObjectName = N'QuoteMemos',	-- nvarchar(255)
									@IsInsert = @IsInsert OUTPUT;	-- bit	


	-- Duplicate the Quote Items. 
	INSERT	SSop.QuoteItems
		 (RowStatus, Guid, QuoteId, ProductId, Details, Net, VatRate, DoNotConsolidateJob, SortOrder, Quantity)
	SELECT	1,
			qil.GuidValueTwo,
			@ID,
			qi.ProductId,
			qi.Details,
			qi.Net,
			qi.VatRate,
			qi.DoNotConsolidateJob,
			qi.SortOrder,
			qi.Quantity
	FROM	SSop.QuoteItems AS qi
	JOIN	@QuoteItems		AS qil ON (qil.GuidValue = qi.Guid);



	-- Duplicate the Quote Payment Stages 
	INSERT INTO SSop.QuotePaymentStages
		 (RowStatus, Guid, QuoteId, PaymentFrequencyTypeId, PaymentFrequency, Value, PercentageOfTotal, PayAfterStageId)
	SELECT	1,
			qpsl.GuidValueTwo,
			@ID,
			qps.PaymentFrequencyTypeId,
			qps.PaymentFrequency,
			qps.Value,
			qps.PercentageOfTotal,
			qps.PayAfterStageId
	FROM	SSop.QuotePaymentStages AS qps
	JOIN	@QuotePaymentStages		AS qpsl ON (qps.Guid = qpsl.GuidValue);


	-- Duplicate the Quote Memos
	INSERT INTO SSop.QuoteMemos
		 (RowStatus, Guid, QuoteID, Memo, CreatedDateTimeUTC, CreatedByUserId)
	SELECT	1,
			qms.GuidValueTwo,
			@ID,
			qm.Memo,
			qm.CreatedDateTimeUTC,
			qm.CreatedByUserId
	FROM	SSop.QuoteMemos AS qm
	JOIN	@QuoteMemos		AS qms ON (qm.Guid = qms.GuidValue);


	-- Allocate a new Quote number. 

	DECLARE @QuoteNumber NVARCHAR(30);

	SELECT	@QuoteNumber = NEXT VALUE FOR SSop.QuoteNumber;

	UPDATE	SSop.Quotes
	SET		Number = @QuoteNumber,
			RowStatus = 1
	WHERE	(ID = @ID);
END;
GO
GO

/* Deploy Function SSop.tvf_EnquiriesValidate using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SSop.tvf_EnquiriesValidate.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create function [SSop].[tvf_EnquiriesValidate]')
GO
CREATE OR ALTER FUNCTION [SSop].[tvf_EnquiriesValidate]
	(
		@Guid UNIQUEIDENTIFIER,
		@RowStatus TINYINT,
		@PropertyGuid UNIQUEIDENTIFIER,
		@ClientAccountGuid UNIQUEIDENTIFIER,
		@ClientAddressGuid UNIQUEIDENTIFIER,
		@AgentAccountGuid UNIQUEIDENTIFIER,
		@AgentAddressGuid UNIQUEIDENTIFIER,
		@FinanceAccountGuid UNIQUEIDENTIFIER,
		@FinanceAddressGuid UNIQUEIDENTIFIER,
		@IsReadyForQuoteReview BIT,
		@DescriptionOfWorks NVARCHAR(MAX),
		@ValueOfWork DECIMAL(19, 2),
		@CurrentProjectRibaStageGuid UNIQUEIDENTIFIER,
		@PropertyNumber NVARCHAR(100),
		@PropertyPostCode NVARCHAR(30),
		@ClientAddressNumber NVARCHAR(100),
		@ClientAddressPostCode NVARCHAR(30),
		@AgentAddressNumber NVARCHAR(100),
		@AgentAddressPostCode NVARCHAR(30),
		@AgentName NVARCHAR(250),
		@ClientName NVARCHAR(250),
		@DeclinedToQuoteDate DATE,
		@DeclinedToQuoteReason NVARCHAR(4000),
		@KeyDates NVARCHAR(2000),
		@DeadDate DATE,
		@EnterNewClientDetails BIT,
		@EnterNewAgentDetails BIT,
		@EnterNewFinanceDetails BIT,
		@EnterNewStructureDetails BIT,
		@IsClientFinanceAccount BIT,
		@ProjectGuid UNIQUEIDENTIFIER,
		@ClientContactDisplayName NVARCHAR(250),
		@AgentContactDisplayName NVARCHAR(250),
		@FinanceContactDisplayName NVARCHAR(250),
		@ClientContactDetailType UNIQUEIDENTIFIER,
		@ClientContactDetailTypeName NVARCHAR(100),
		@ClientContactDetailTypeValue NVARCHAR(250),
		@AgentContactDetailType UNIQUEIDENTIFIER,
		@AgentContactDetailTypeName NVARCHAR(100),
		@AgentContactDetailTypeValue NVARCHAR(250),
		@FinanceContactDetailType UNIQUEIDENTIFIER,
		@FinanceContactDetailTypeName NVARCHAR(100),
		@FinanceContactDetailTypeValue NVARCHAR(250),
		@ContractGuid UNIQUEIDENTIFIER,
		@AgentContractGuid UNIQUEIDENTIFIER
	)
RETURNS @ValidationResult TABLE
	(
		ID INT IDENTITY(1, 1) NOT NULL,
		TargetGuid UNIQUEIDENTIFIER NOT NULL DEFAULT ('00000000-0000-0000-0000-000000000000'),
		TargetType CHAR(1) NOT NULL DEFAULT (''),
		IsReadOnly BIT NOT NULL DEFAULT ((0)),
		IsHidden BIT NOT NULL DEFAULT ((0)),
		IsInvalid BIT NOT NULL DEFAULT ((0)),
		IsInformationOnly BIT NOT NULL DEFAULT ((0)),
		Message NVARCHAR(2000) NOT NULL DEFAULT ('')
	)
AS
BEGIN

	DECLARE @EntityPropertyGuid UNIQUEIDENTIFIER;

	DECLARE @ReadyForQuoteStatus	UNIQUEIDENTIFIER = 'EB867FA0-9608-4CC7-93BE-CC8E8140E8F0';
	DECLARE @DeadStatus				UNIQUEIDENTIFIER = '8C7F7526-559F-4CCF-8FC2-DB0DA67E793D';
	DECLARE @DeclinedStatus			UNIQUEIDENTIFIER = N'708C00E6-F45F-4CB2-8E91-A80B8B8E802E';
	DECLARE @ReOpened				UNIQUEIDENTIFIER = '34EF363A-C8F7-4BA8-A2C6-067EBAEF12FD';

	

	DECLARE @DeclinedToQuote	 DATE;
	DECLARE @IsDeadDate			 DATE;
	DECLARE @ReadyForQuoteReview BIT = 0;


	DECLARE @IsEnquiryReopened  BIT = 0;


	IF(EXISTS
				(
					SELECT 1 
					FROM SCore.DataObjectTransition AS dot 
					JOIN SCore.WorkflowStatus AS ws ON (ws.ID = dot.StatusID) 
					WHERE 
							(dot.DataObjectGuid = @Guid) 
						AND (ws.Guid = @ReOpened)
						AND dot.RowStatus NOT IN (0,254)
						--No other transition after "Reopened"
						AND NOT EXISTS
								(
									SELECT 1 
									FROM SCore.DataObjectTransition AS dot1 
									JOIN SCore.WorkflowStatus AS ws ON (ws.ID = dot1.StatusID) 
									WHERE 
											(dot1.DataObjectGuid = @Guid)
										AND (dot1.RowStatus NOT IN (0,254))
										AND (ws.RowStatus NOT IN (0,254))
										AND (dot1.ID > dot.ID)
								)
				)
			)
		SET @IsEnquiryReopened = 1;
	
	

	--Declined
	IF(EXISTS
		(
			SELECT 1 
			FROM SCore.DataObjectTransition AS dot
			JOIN SCore.WorkflowStatus AS ws ON (ws.ID = StatusID)
			WHERE 
				(dot.DataObjectGuid = @Guid) 
				AND (dot.RowStatus NOT IN (0,254))
				AND (ws.Guid = @DeclinedStatus)
		)
	)
	BEGIN
			SELECT @DeclinedToQuote = dot.DateTimeUTC
			FROM SCore.DataObjectTransition AS dot
			JOIN SCore.WorkflowStatus AS ws ON (ws.ID = StatusID)
			WHERE 
				(dot.DataObjectGuid = @Guid) 
				AND (dot.RowStatus NOT IN (0,254))
				AND (ws.Guid = @DeclinedStatus)
	END;

	--Dead
	ELSE IF(EXISTS
			(
				SELECT 1 
				FROM SCore.DataObjectTransition AS dot
				JOIN SCore.WorkflowStatus AS ws ON (ws.ID = StatusID)
				WHERE 
					(dot.DataObjectGuid = @Guid) 
					AND (dot.RowStatus NOT IN (0,254))
					AND (ws.Guid = @DeadStatus)
			)
	)
	BEGIN
			SELECT @IsDeadDate = dot.DateTimeUTC
			FROM SCore.DataObjectTransition AS dot
			JOIN SCore.WorkflowStatus AS ws ON (ws.ID = StatusID)
			WHERE 
				(dot.DataObjectGuid = @Guid) 
				AND (dot.RowStatus NOT IN (0,254))
				AND (ws.Guid = @DeadStatus)
	END;


	--Ready for quote review
	ELSE IF(EXISTS
			(
				SELECT 1 
				FROM SCore.DataObjectTransition AS dot
				JOIN SCore.WorkflowStatus AS ws ON (ws.ID = StatusID)
				WHERE 
					(dot.DataObjectGuid = @Guid) 
					AND (dot.RowStatus NOT IN (0,254))
					AND (ws.Guid = @ReadyForQuoteStatus)
			)
	)
	BEGIN
			SET @ReadyForQuoteReview = 1;
	END;



	/*
		Hide the old key dates field if it wasn't populated. 
	*/
	IF (@KeyDates = N'')
	BEGIN
		INSERT	@ValidationResult
			 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
		SELECT	epfvv.Guid,
				N'P',
				0,
				1,
				0,
				N''
		FROM	SCore.EntityPropertiesForValidationV AS epfvv
		WHERE	epfvv.[Schema] = N'SSop'
			AND epfvv.Hobt	   = N'Enquiries'
			AND epfvv.Name	   = N'KeyDates';
	END;

	
	/*
		If there's both a declined to quote date and reason, lock these fields down. 
	*/
	IF (@DeclinedToQuote IS NOT NULL OR @DeclinedToQuoteDate IS NOT NULL)
	BEGIN
		INSERT	@ValidationResult
			 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
		SELECT	epfvv.Guid,
				N'P',
				1,
				0,
				0,
				N''
		FROM	SCore.EntityPropertiesForValidationV AS epfvv
		WHERE	epfvv.[Schema] = N'SSop'
			AND epfvv.Hobt	   = N'Enquiries'
			AND epfvv.Name NOT IN (N'DeclinedToQuoteDate', N'DeclinedToQuoteReason');
	END;

	/* 
		If there's a dead date. Lock everything down except that field. 
	*/
	IF ((@IsDeadDate IS NOT NULL OR @DeadDate IS NOT NULL) AND @IsEnquiryReopened = 0)
	BEGIN
		INSERT	@ValidationResult
			 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
		SELECT	epfvv.Guid,
				N'P',
				1,
				0,
				0,
				N''
		FROM	SCore.EntityPropertiesForValidationV AS epfvv
		WHERE	epfvv.[Schema] = N'SSop'
			AND epfvv.Hobt	   = N'Enquiries'
			AND epfvv.Name	   <> N'DeadDate';
	END;

	/* Hide show manual property entry.  */
	IF (
		   @PropertyGuid <> '00000000-0000-0000-0000-000000000000'
		OR	@EnterNewStructureDetails = 0
	   )
	BEGIN
		INSERT	@ValidationResult
			 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
		SELECT	epfvv.Guid,
				N'P',
				0,
				1,
				0,
				N''
		FROM	SCore.EntityPropertiesForValidationV AS epfvv
		WHERE	epfvv.[Schema] = N'SSop'
			AND epfvv.Hobt	   = N'Enquiries'
			AND epfvv.Name IN (N'PropertyNameNumber', N'PropertyAddressLine1', N'PropertyAddressLine2',
							   N'PropertyAddressLine3', N'PropertyTown', N'PropertyCountyId', N'PropertyPostCode',
							   N'PropertyCountryId'
							  
							  );
	END;
	ELSE
	BEGIN
		INSERT	@ValidationResult
			 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
		SELECT	epfvv.Guid,
				N'P',
				0,
				1,
				0,
				N''
		FROM	SCore.EntityPropertiesForValidationV AS epfvv
		WHERE	epfvv.[Schema] = N'SSop'
			AND epfvv.Hobt	   = N'Enquiries'
			AND epfvv.Name IN (N'PropertyID');
	END;

	/*
		Ensure that if the user is manually entering the client/agent/finance details - along with contact details -
		that any field pertaining to the contact details are made compulsory once the "...ContactDisplayName" has been filled.
	*/

	--Client
	IF (
			@EnterNewClientDetails = 1 AND 
			@ClientContactDisplayName <> N'' AND 
			(
				@ClientContactDetailType = '00000000-0000-0000-0000-000000000000' OR
				@ClientContactDetailTypeName = N'' OR
				@ClientContactDetailTypeValue = N''
			)
		)
	BEGIN
	INSERT	@ValidationResult
				 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
			SELECT	epfvv.Guid,
					N'P',
					0,
					0,
					1,
					N'Please enter contact details for client.'
			FROM	SCore.EntityPropertiesForValidationV AS epfvv
			WHERE	epfvv.[Schema] = N'SSop'
				AND epfvv.Hobt	   = N'Enquiries'
				AND epfvv.Name IN (N'ClientContactDetailType', N'ClientContactDetailTypeName',N'ClientContactDetailTypeValue', N'');

	END;


	--Agent
	IF (
			@EnterNewAgentDetails = 1 AND 
			@AgentContactDisplayName <> N'' AND
			(
				@AgentContactDetailType = '00000000-0000-0000-0000-000000000000' OR
				@AgentContactDetailTypeName = N'' OR
				@AgentContactDetailTypeValue = N''
			)
		)
	BEGIN
	INSERT	@ValidationResult
				 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
			SELECT	epfvv.Guid,
					N'P',
					0,
					0,
					1,
					N'Please enter contact details for agent account.'
			FROM	SCore.EntityPropertiesForValidationV AS epfvv
			WHERE	epfvv.[Schema] = N'SSop'
				AND epfvv.Hobt	   = N'Enquiries'
				AND epfvv.Name IN (N'AgentContactDetailType', N'AgentContactDetailTypeName',N'AgentContactDetailTypeValue', N'');

	END;

	--Finance
	IF (
			@EnterNewFinanceDetails = 1 AND 
			@FinanceContactDisplayName <> N'' AND
			(
				@FinanceContactDetailType = '00000000-0000-0000-0000-000000000000' OR
				@FinanceContactDetailTypeName = N'' OR
				@FinanceContactDetailTypeValue = N''
			)
		)
	BEGIN
	INSERT	@ValidationResult
				 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
			SELECT	epfvv.Guid,
					N'P',
					0,
					0,
					1,
					N'Please enter contact details for finance account.'
			FROM	SCore.EntityPropertiesForValidationV AS epfvv
			WHERE	epfvv.[Schema] = N'SSop'
				AND epfvv.Hobt	   = N'Enquiries'
				AND epfvv.Name IN (N'FinanceContactDetailType', N'FinanceContactDetailTypeName',N'FinanceContactDetailTypeValue', N'');

	END;

	/* Hide / Show Manual Client Entry */
	IF (
		   @ClientAccountGuid <> '00000000-0000-0000-0000-000000000000'
		OR	@EnterNewClientDetails = 0
	   )
	BEGIN
		INSERT	@ValidationResult
			 (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
		SELECT	epfvv.Guid,
				N'P',
				0,
				1,
